-- Production import generated from the verified local questionnaire CSV exports.
-- Source: q_versions.csv, q.csv, q_options.csv exported 2026-09-03.
-- IMPORTANT: Back up bcd_application2 and bcd_questionnaire before running.
-- This replaces Version 2 only. Version 1 questions/options/translations are preserved.
SET NAMES utf8mb4;
USE bcd_application2;

CREATE TABLE IF NOT EXISTS questionnaire_versions (
  version_number INT NOT NULL PRIMARY KEY,
  version_name VARCHAR(100) NOT NULL,
  description TEXT NULL,
  is_active TINYINT NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  activated_at TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP PROCEDURE IF EXISTS ensure_questionnaire_v2_schema;
DELIMITER $$
CREATE PROCEDURE ensure_questionnaire_v2_schema()
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND COLUMN_NAME='question_key') THEN ALTER TABLE questions ADD COLUMN question_key VARCHAR(50) NULL AFTER id; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND COLUMN_NAME='version_number') THEN ALTER TABLE questions ADD COLUMN version_number INT NOT NULL DEFAULT 1 AFTER question_key; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND COLUMN_NAME='display_order') THEN ALTER TABLE questions ADD COLUMN display_order INT NOT NULL DEFAULT 0 AFTER version_number; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND COLUMN_NAME='step_value') THEN ALTER TABLE questions ADD COLUMN step_value INT NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND COLUMN_NAME='video_url') THEN ALTER TABLE questions ADD COLUMN video_url VARCHAR(255) NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND COLUMN_NAME='other_option_id') THEN ALTER TABLE questions ADD COLUMN other_option_id VARCHAR(50) NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND COLUMN_NAME='other_placeholder') THEN ALTER TABLE questions ADD COLUMN other_placeholder VARCHAR(255) NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND COLUMN_NAME='parent_question_id') THEN ALTER TABLE questions ADD COLUMN parent_question_id INT NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND COLUMN_NAME='trigger_answer') THEN ALTER TABLE questions ADD COLUMN trigger_answer VARCHAR(255) NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND INDEX_NAME='uq_questions_version_key') THEN ALTER TABLE questions ADD UNIQUE KEY uq_questions_version_key(version_number,question_key); END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='questions' AND INDEX_NAME='idx_questions_version_order') THEN ALTER TABLE questions ADD KEY idx_questions_version_order(version_number,display_order); END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_application2' AND TABLE_NAME='patient_sessions' AND COLUMN_NAME='questionnaire_version') THEN ALTER TABLE patient_sessions ADD COLUMN questionnaire_version INT NOT NULL DEFAULT 1; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='bcd_questionnaire') THEN
    IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_questionnaire' AND TABLE_NAME='session_table' AND COLUMN_NAME='questionnaire_version') THEN ALTER TABLE bcd_questionnaire.session_table ADD COLUMN questionnaire_version INT NOT NULL DEFAULT 1; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_questionnaire' AND TABLE_NAME='session_data_table' AND COLUMN_NAME='question_key') THEN ALTER TABLE bcd_questionnaire.session_data_table ADD COLUMN question_key VARCHAR(50) NULL; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bcd_questionnaire' AND TABLE_NAME='session_data_table' AND COLUMN_NAME='questionnaire_version') THEN ALTER TABLE bcd_questionnaire.session_data_table ADD COLUMN questionnaire_version INT NOT NULL DEFAULT 1; END IF;
  END IF;
END$$
DELIMITER ;
CALL ensure_questionnaire_v2_schema();
DROP PROCEDURE ensure_questionnaire_v2_schema;

