CREATE TABLE IF NOT EXISTS participant_information_translations (
  version_number INT NOT NULL,
  language_code VARCHAR(5) NOT NULL,
  content_json JSON NOT NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (version_number, language_code),
  KEY idx_participant_information_active (version_number, is_active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;



-- Activate V2 only after every question and option has been inserted.
