-- Verification: expected V2 totals are 65 questions and 223 options.
SELECT version_number,version_name,is_active,activated_at FROM questionnaire_versions ORDER BY version_number;
SELECT COUNT(*) AS v2_question_count FROM questions WHERE version_number=2;
SELECT COUNT(*) AS v2_option_count FROM question_options qo JOIN questions q ON q.id=qo.question_id WHERE q.version_number=2;
SELECT child.question_key,parent.question_key AS parent_key,child.trigger_answer FROM questions child LEFT JOIN questions parent ON parent.id=child.parent_question_id WHERE child.version_number=2 ORDER BY child.display_order,child.id;
