INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'bn','{"title":"গবেষণা সম্পর্কে অংশগ্রহণকারীর তথ্য","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"গবেষণার শিরোনাম","sponsor":"পৃষ্ঠপোষক","iecApproval":"IEC অনুমোদন"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) আমন্ত্রণ ও স্বেচ্ছায় অংশগ্রহণ","paragraphs":[{"text":"ভারতীয় জনগণের মধ্যে স্তন ক্যান্সারের ঝুঁকির কারণগুলি নিয়ে একটি গবেষণায় অংশগ্রহণ করার জন্য আপনাকে আমন্ত্রণ জানানো হচ্ছে। অংশগ্রহণ সম্পূর্ণরূপে স্বেচ্ছামূলক। আপনি অংশগ্রহণ না করার সিদ্ধান্ত নিতে পারেন এবং এতে আপনার কোনো ক্ষতি বা অসুবিধা হবে না।"},{"strong":"যোগ্যতা:","text":"আপনার বয়স ১৮ বছর বা তার বেশি হতে হবে। আপনি যদি ১৮ বছরের নিচে হন, অনুগ্রহ করে এগিয়ে যাবেন না।","className":"sub-point"}]},{"heading":"2) গবেষণার উদ্দেশ্য","paragraphs":[{"text":"ভারতে স্তন ক্যান্সারের ঝুঁকির কারণগুলি বোঝার জন্য এবং ৫ বছরের ও আজীবন ঝুঁকি নির্ধারণের একটি গবেষণা মডেল তৈরি করার জন্য জরিপের উত্তরগুলি বিশ্লেষণ করা হবে। এই টুলটি এখনও উন্নয়নাধীন, এটি চিকিৎসা ব্যবহারের জন্য নয়, এবং এটি কোনো রোগ নির্ণয় বা চিকিৎসা প্রদান করে না।"}]},{"heading":"3) আপনি কী করবেন","paragraphs":[{"text":"জনসংখ্যা ও স্বাস্থ্যের সাথে সম্পর্কিত বিষয়গুলিতে একটি এককালীন প্রশ্নাবলী পূরণ করুন। আনুমানিক সময় প্রায় ৫–৭ মিনিট। আপনি যেকোনো অস্বস্তিকর প্রশ্ন এড়িয়ে যেতে পারেন।"}]},{"heading":"4) ঝুঁকি ও অস্বস্তি","paragraphs":[{"text":"ঝুঁকি ন্যূনতম, তবে কিছু ব্যক্তিগত প্রশ্ন অস্বস্তিকর হতে পারে। \\"ডেটা ও গোপনীয়তা\\" বিভাগে বর্ণিত সুরক্ষা ব্যবস্থা দ্বারা তথ্য ফাঁসের ঝুঁকি হ্রাস করা হয়েছে।"}]},{"heading":"5) উপকারিতা","paragraphs":[{"text":"আপনার সরাসরি কোনো উপকার নাও হতে পারে। এই গবেষণার ফলাফল ভারতে স্তন ক্যান্সারের ঝুঁকির কারণগুলি বোঝার উন্নতি করতে এবং ভবিষ্যতের গবেষণার সরঞ্জাম উন্নয়নে সাহায্য করতে পারে।"}]},{"heading":"6) গুরুত্বপূর্ণ: শুধুমাত্র গবেষণার জন্য; চিকিৎসা পরামর্শ নয়","className":"important-notice","paragraphs":[{"text":"এই টুল থেকে প্রাপ্ত যেকোনো স্কোর বা ফলাফল শুধুমাত্র গবেষণার উদ্দেশ্যে। এটি পেশাদার চিকিৎসা পরামর্শ, রোগ নির্ণয় বা চিকিৎসার বিকল্প নয়। এই টুলটি CDSCO দ্বারা অনুমোদিত নয় এবং এটি একটি মেডিকেল সফটওয়্যার (SaMD) হিসাবে প্রত্যয়িত নয়। যেকোনো স্বাস্থ্য উদ্বেগের জন্য, দয়া করে একজন যোগ্য চিকিৎসকের সাথে পরামর্শ করুন।"}]},{"heading":"7) ডেটা ও গোপনীয়তা (বেনামী জরিপ)","paragraphs":[{"text":"আমরা কোনো ব্যক্তিগত শনাক্তযোগ্য তথ্য (যেমন নাম, ফোন, ইমেল, সঠিক ঠিকানা, জাতীয় আইডি) সংগ্রহ করি না। উত্তরগুলি আপনার পরিচয়ের সাথে সংযুক্ত নয়। একবার আপনি আপনার উত্তর জমা দিলে, আমরা তা মুছতে বা প্রত্যাহার করতে পারব না কারণ আমরা জানি না কোন উত্তর আপনার।"},{"strong":"প্রযুক্তিগত লগ:","text":"আমাদের সিস্টেমগুলি আইপি ঠিকানা বা ডিভাইস শনাক্তকারী সাময়িক প্রক্রিয়াকরণের বাইরে সংরক্ষণ না করার জন্য কনফিগার করা হয়েছে। নিরাপত্তা বা কর্মক্ষমতার জন্য সামান্য লগ তৈরি হলেও, সেগুলি আপনার উত্তরের সাথে সংযুক্ত নয় এবং নীতিমালা অনুযায়ী মুছে ফেলা হয়।","className":"sub-point"},{"strong":"নিরাপত্তা:","text":"ডেটা নিরাপদ, অ্যাক্সেস-নিয়ন্ত্রিত সিস্টেমে সংরক্ষিত থাকে, যেখানে এনক্রিপশন এবং ভূমিকা-ভিত্তিক অ্যাক্সেস নিয়ন্ত্রণের মতো প্রযুক্তিগত ও সাংগঠনিক ব্যবস্থা রয়েছে।","className":"sub-point"}]},{"heading":"8) ডেটার ব্যবহার, শেয়ারিং ও সংরক্ষণ","paragraphs":[{"strong":"উদ্দেশ্য সীমাবদ্ধতা:","text":"ডেটা কেবলমাত্র স্তন ক্যান্সারের ঝুঁকির কারণ এবং মডেল উন্নয়ন/যাচাই সংক্রান্ত একাডেমিক গবেষণার জন্য ব্যবহৃত হবে।","className":"sub-point"},{"strong":"শেয়ারিং:","text":"শুধুমাত্র বেনামী বা সংকলিত ডেটাসেট গবেষণা সহযোগী ও একাডেমিক অংশীদারদের সাথে একই উদ্দেশ্যে ভাগ করা যেতে পারে। প্রকাশনাগুলি ব্যক্তিদের শনাক্ত না করে সামগ্রিক ফলাফল রিপোর্ট করবে।","className":"sub-point"},{"strong":"সংরক্ষণ:","text":"বেনামী ডেটাসেটগুলি পুনরুত্পাদনযোগ্যতা এবং নিরীক্ষার উদ্দেশ্যে প্রতিষ্ঠান/IEC নীতিমালা অনুযায়ী সংরক্ষণ করা যেতে পারে।","className":"sub-point"}]},{"heading":"9) খরচ ও ক্ষতিপূরণ","paragraphs":[{"text":"আপনার অংশগ্রহণের জন্য কোনো খরচ নেই, এবং আপনি কোনো পারিশ্রমিক পাবেন না। এটি একটি ন্যূনতম ঝুঁকির জরিপ গবেষণা হওয়ায়, আঘাতের জন্য কোনো ক্ষতিপূরণ প্রদান করা হবে না।"}]},{"heading":"10) যোগাযোগের তথ্য (Contact Information)","paragraphs":[{"text":"আপনি যদি গবেষণার সাথে সম্পর্কিত নন এমন কারো সাথে কথা বলতে চান, তবে আপনি যোগাযোগ করতে পারেন:"},{"strong":"প্রাতিষ্ঠানিক নীতিশাস্ত্র কমিটি (IEC)","text":""},{"strong":"নাম (Name):","text":"Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH"},{"strong":"ইমেল (Email):","text":"secretary.iec@tanuh.ai"},{"strong":"ফোন (Phone#):","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"স্বীকার করুন ও চালিয়ে যান"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'en','{"title":"Participant Information about the Study","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"Study Title","sponsor":"Sponsor","iecApproval":"IEC Approval"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) Invitation & Voluntary Participation","paragraphs":[{"text":"You are invited to take part in a research study about breast cancer risk factors in the Indian population. Participation is entirely voluntary. You may decline to participate without any penalty or loss of benefits."},{"strong":"Eligibility:","text":"You must be 18 years or older. If you are under 18, please do not proceed.","className":"sub-point"}]},{"heading":"2) Purpose of the Study","paragraphs":[{"text":"We will analyze survey responses to understand breast cancer risk factors in India and to develop a research-only model that estimates 5-year and lifetime risk. This tool is under development, not for clinical use, and does not provide a medical diagnosis or treatment."}]},{"heading":"3) What You Will Do","paragraphs":[{"text":"Complete a one-time questionnaire on demographic and health-related factors. The estimated time is approximately 5-7 minutes. You may skip any question you are uncomfortable answering."}]},{"heading":"4) Risks & Discomforts","paragraphs":[{"text":"The risks are minimal and may include discomfort with personal questions. There is a small risk of a data breach, for which we apply the safeguards described in the \\"Data & Privacy\\" section below."}]},{"heading":"5) Benefits","paragraphs":[{"text":"There may be no direct benefit to you. The findings may improve the understanding of breast cancer risk factors in India and guide future research tools."}]},{"heading":"6) Important: Research-Only; Not Medical Advice","className":"important-notice","paragraphs":[{"text":"Any score or output from this tool is experimental and for research purposes only. It is not a substitute for professional medical advice, diagnosis, or treatment. This tool is not approved by CDSCO and is not a certified Software as a Medical Device (SaMD). For any health concerns, please consult a qualified physician."}]},{"heading":"7) Data & Privacy (Anonymous Survey)","paragraphs":[{"text":"We do not collect any personal identifiers (e.g., name, phone, email, precise address, national ID). Responses are recorded without any link to your identity. Because submissions are anonymous, once you submit your responses, they cannot be withdrawn or deleted, as we cannot identify which responses are yours."},{"strong":"Technical logs:","text":"We configure systems to avoid storing IP addresses or device identifiers beyond transient processing. If minimal infrastructure logs are generated for security or performance, they are not linked to your responses and are deleted per institutional policy.","className":"sub-point"},{"strong":"Security:","text":"Data are stored on secure, access-controlled systems with reasonable technical and organizational measures, such as encryption and role-based access controls.","className":"sub-point"}]},{"heading":"8) Data Use, Sharing & Retention","paragraphs":[{"strong":"Purpose limitation:","text":"Data will be used exclusively for academic research on breast cancer risk factors and model development/validation.","className":"sub-point"},{"strong":"Sharing:","text":"Only de-identified or aggregated datasets may be shared with research collaborators and academic partners for the same purpose. Publications will report aggregate results that do not identify individuals.","className":"sub-point"},{"strong":"Retention:","text":"Anonymous datasets may be retained as per institutional/IEC policy for reproducibility and audit.","className":"sub-point"}]},{"heading":"9) Costs & Compensation","paragraphs":[{"text":"There is no cost to you for participating, and you will not be paid. No compensation is available for injury, as this is a minimal-risk, survey-only study."}]},{"heading":"10) Contact Information","paragraphs":[{"text":"If you wish to speak to someone independent of the study, you may contact the:"},{"strong":"Institutional Ethics Committee (IEC)","text":""},{"strong":"Name:","text":"Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH"},{"strong":"Email:","text":"secretary.iec@tanuh.ai"},{"strong":"Phone#","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"Accept & Continue"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'gu','{"title":"અભ્યાસ વિશે સહભાગી માહિતી","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"અભ્યાસ શીર્ષક","sponsor":"પ્રાયોજક","iecApproval":"IEC મંજૂરી"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) આમંત્રણ અને સ્વૈચ્છિક ભાગીદારી","paragraphs":[{"text":"ભારતીય વસ્તીમાં સ્તન કૅન્સરના જોખમકારક પરિબળો વિશેના સંશોધનમાં ભાગ લેવા માટે તમને આમંત્રિત કરવામાં આવે છે. ભાગ લેવું સંપૂર્ણપણે સ્વૈચ્છિક છે. તમે ભાગ ન લેવાનો નિર્ણય કરી શકો છો અને તેની કોઈ સજા અથવા લાભ ગુમાવવાનો ખતરો નથી."},{"strong":"પાત્રતા:","text":"તમારી ઉંમર ઓછામાં ઓછી 18 વર્ષ હોવી જોઈએ. જો તમારી ઉંમર 18 વર્ષથી ઓછી હોય, તો કૃપા કરીને આગળ વધશો નહીં.","className":"sub-point"}]},{"heading":"2) અભ્યાસનો હેતુ","paragraphs":[{"text":"અમે ભારતના સ્તન કૅન્સરના જોખમકારક પરિબળોને સમજવા અને 5 વર્ષ અને જીવનભરના જોખમનો અંદાજ લગાવનારા સંશોધન મોડલને વિકસાવવા માટે સર્વેના જવાબોનું વિશ્લેષણ કરીશું. આ સાધન હજી વિકાસ હેઠળ છે, તે તબીબી ઉપયોગ માટે નથી અને તે કોઈ નિદાન કે સારવાર પૂરું પાડતું નથી."}]},{"heading":"3) તમે શું કરશો","paragraphs":[{"text":"લોકગણતરી અને આરોગ્ય સંબંધિત પરિબળો વિશેની એક વખતની પ્રશ્નાવલી ભરો. અંદાજિત સમય લગભગ 5–7 મિનિટ છે. તમે જે પ્રશ્નોના જવાબ આપવા અસમર્થ હો, તે પ્રશ્નો છોડો."}]},{"heading":"4) જોખમો અને અસુવિધાઓ","paragraphs":[{"text":"જોખમ ખૂબ ઓછા છે, પરંતુ કેટલાક વ્યક્તિગત પ્રશ્નો તમને અસુવિધા પેદા કરી શકે છે. \\"ડેટા અને પ્રાઇવસી\\" વિભાગમાં વર્ણવેલા સુરક્ષા ઉપાયો દ્વારા ડેટા લીક થવાનો જોખમ ઘટાડવામાં આવ્યો છે."}]},{"heading":"5) લાભો","paragraphs":[{"text":"તમને સીધો કોઈ લાભ નહીં મળે. શોધો ભારતના સ્તન કૅન્સરના જોખમકારક પરિબળોને સમજવામાં અને ભવિષ્યના સંશોધન સાધનોના વિકાસમાં મદદરૂપ થઈ શકે છે."}]},{"heading":"6) મહત્વપૂર્ણ: ફક્ત સંશોધન માટે; તબીબી સલાહ નથી","className":"important-notice","paragraphs":[{"text":"આ સાધનમાંથી મળેલો કોઈપણ સ્કોર અથવા પરિણામ ફક્ત સંશોધન માટે છે. તે વ્યાવસાયિક તબીબી સલાહ, નિદાન અથવા સારવારનો વિકલ્પ નથી. આ સાધન CDSCO દ્વારા મંજૂર નથી અને તે મેડિકલ સોફ્ટવેર (SaMD) તરીકે પ્રમાણિત પણ નથી. કોઈપણ આરોગ્ય સંબંધિત ચિંતાઓ માટે કૃપા કરીને લાયકાતપ્રાપ્ત ડૉક્ટરનો સંપર્ક કરો."}]},{"heading":"7) ડેટા અને પ્રાઇવસી (અજ્ઞાત સર્વે)","paragraphs":[{"text":"અમે કોઈપણ વ્યક્તિગત ઓળખ માહિતી (જેમ કે નામ, ફોન, ઇમેલ, સરનામું, ઓળખપત્ર) એકત્રિત કરતા નથી. જવાબો તમારી ઓળખ સાથે જોડાયેલા નથી. એક વાર તમે તમારા જવાબો સબમિટ કરો, પછી અમે તેને કાઢી શકતા નથી કારણ કે અમે જાણી શકતા નથી કે કયા જવાબો તમારા છે."},{"strong":"ટેકનિકલ લોગ્સ:","text":"અમે સિસ્ટમોને IP સરનામાંઓ અથવા ઉપકરણ ઓળખને તાત્કાલિક પ્રક્રિયાથી આગળ સ્ટોર ન કરવા માટે ગોઠવી છે. જો સુરક્ષા અથવા પ્રદર્શન માટે ઓછા પ્રમાણમાં લોગ્સ ઉત્પન્ન થાય, તો તેઓ તમારા જવાબો સાથે જોડાયેલા નથી અને સંસ્થાની નીતિ મુજબ કાઢી નાખવામાં આવે છે.","className":"sub-point"},{"strong":"સુરક્ષા:","text":"ડેટા સુરક્ષિત, ઍક્સેસ-નિયંત્રિત સિસ્ટમોમાં સંગ્રહિત છે જેમાં એનક્રિપ્શન અને ભૂમિકા આધારિત ઍક્સેસ નિયંત્રણ જેવા યોગ્ય તકનીકી અને સંગઠનાત્મક ઉપાયો છે.","className":"sub-point"}]},{"heading":"8) ડેટાનો ઉપયોગ, શેરિંગ અને જાળવણી","paragraphs":[{"strong":"હેતુ મર્યાદા:","text":"ડેટાનો ઉપયોગ ફક્ત સ્તન કૅન્સરના જોખમકારક પરિબળો અને મોડેલ વિકાસ/માન્યતા માટેના શૈક્ષણિક સંશોધન માટે જ કરવામાં આવશે.","className":"sub-point"},{"strong":"શેરિંગ:","text":"ફક્ત અજ્ઞાત અથવા એકત્રિત ડેટાસેટ્સ સંશોધન સહયોગી અને શૈક્ષણિક ભાગીદારો સાથે સમાન હેતુ માટે શેર કરી શકાય છે. પ્રકાશનોમાં વ્યક્તિઓની ઓળખ કર્યા વગર સંયુક્ત પરિણામો દર્શાવવામાં આવશે.","className":"sub-point"},{"strong":"જાળવણી:","text":"અજ્ઞાત ડેટાસેટ્સ સંસ્થા/IEC નીતિ મુજબ પુનઃપ્રતિ અને ઑડિટ માટે જાળવી શકાય છે.","className":"sub-point"}]},{"heading":"9) ખર્ચ અને વળતર","paragraphs":[{"text":"ભાગ લેવા માટે તમારે કોઈ ખર્ચ કરવો નહીં પડે અને તમને કોઈ ચુકવણી કરવામાં નહીં આવે. આ ન્યૂનતમ જોખમવાળું સર્વે અભ્યાસ છે, તેથી ઇજા માટે કોઈ વળતર ઉપલબ્ધ નથી."}]},{"heading":"10) સંપર્ક માહિતી (Contact Information)","paragraphs":[{"text":"જો તમે અભ્યાસથી સ્વતંત્ર કોઈ વ્યક્તિ સાથે વાત કરવા માંગતા હોવ, તો તમે સંપર્ક કરી શકો છો:"},{"strong":"સંસ્થાકીય નીતિશાસ્ત્ર સમિતિ (IEC)","text":""},{"strong":"નામ (Name):","text":"Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH"},{"strong":"ઇમેઇલ (Email):","text":"secretary.iec@tanuh.ai"},{"strong":"ફોન (Phone#):","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"સ્વીકારો અને આગળ વધો"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'hi','{"title":"अध्ययन के बारे में प्रतिभागी जानकारी","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"अध्ययनशीर्षक","sponsor":"प्रायोजक","iecApproval":"आईईसीअनुमोदन"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) आमंत्रण और स्वैच्छिक भागीदारी","paragraphs":[{"text":"आपको भारतीय जनसंख्या में स्तन कैंसर जोखिम कारकों पर अनुसंधान अध्ययन में भाग लेने के लिए आमंत्रित किया गया है। भागीदारी पूरी तरह स्वैच्छिक है। आप किसी भी समय बिना किसी हानि या लाभ के नुकसान के अध्ययन में भाग न लेने का विकल्प चुन सकते हैं।"},{"strong":"पात्रता:","text":"आपकी आयु 18 वर्ष या उससे अधिक होनी चाहिए। यदि आपकी आयु 18 वर्ष से कम है, तो कृपया आगे न बढ़ें।","className":"sub-point"}]},{"heading":"2) अध्ययन का उद्देश्य","paragraphs":[{"text":"हम भारत में स्तन कैंसर जोखिम कारकों को समझने और 5-वर्ष तथा आजीवन जोखिम का अनुमान लगाने वाले एक शोध-केवल मॉडल को विकसित करने के लिए सर्वेक्षण उत्तरों का विश्लेषण करेंगे। यह उपकरण विकासाधीन है, चिकित्सीय उपयोग के लिए नहीं है, और किसी भी प्रकार का चिकित्सीय निदान या उपचार प्रदान नहीं करता।"}]},{"heading":"3) आपको क्या करना होगा","paragraphs":[{"text":"जनसांख्यिकी और स्वास्थ्य-संबंधी कारकों पर एक बार का प्रश्नावली भरें। अनुमानित समय लगभग 5–7 मिनट है। आप किसी भी ऐसे प्रश्न को छोड़ सकते हैं जिसका उत्तर देने में आप असहज हों।"}]},{"heading":"4) जोखिम और असुविधाएँ","paragraphs":[{"text":"जोखिम न्यूनतम हैं और इनमें व्यक्तिगत प्रश्नों से असुविधा शामिल हो सकती है। डेटा उल्लंघन का एक छोटा जोखिम है, जिसके लिए नीचे दिए गए \\"डेटा और गोपनीयता\\" अनुभाग के अनुसार सुरक्षा उपाय लागू किए जाते हैं।"}]},{"heading":"5) लाभ","paragraphs":[{"text":"आपको प्रत्यक्ष लाभ नहीं मिल सकता है। निष्कर्ष भारत में स्तन कैंसर जोखिम कारकों की समझ में सुधार कर सकते हैं और भविष्य के अनुसंधान उपकरणों का मार्गदर्शन कर सकते हैं।"}]},{"heading":"6) महत्वपूर्ण: केवल अनुसंधान; चिकित्सीय सलाह नहीं","className":"important-notice","paragraphs":[{"text":"इस उपकरण से प्राप्त कोई भी स्कोर या आउटपुट प्रयोगात्मक है और केवल अनुसंधान उद्देश्य के लिए है। यह किसी भी पेशेवर चिकित्सा सलाह, निदान या उपचार का विकल्प नहीं है। यह उपकरण CDSCO द्वारा अनुमोदित नहीं है और मेडिकल डिवाइस (SaMD) के रूप में प्रमाणित नहीं है। किसी भी स्वास्थ्य संबंधी चिंता के लिए कृपया योग्य चिकित्सक से संपर्क करें।"}]},{"heading":"7) डेटा और गोपनीयता (गुमनाम सर्वेक्षण)","paragraphs":[{"text":"हम कोई भी व्यक्तिगत पहचानकर्ता (जैसे नाम, फोन, ईमेल, सटीक पता, राष्ट्रीय पहचान) एकत्र नहीं करते। उत्तर आपकी पहचान से जुड़े बिना रिकॉर्ड किए जाते हैं। क्योंकि प्रस्तुतियाँ गुमनाम हैं, एक बार जमा हो जाने के बाद उत्तरों को हटाया या वापस नहीं लिया जा सकता, क्योंकि हम यह नहीं जान सकते कि कौन सा उत्तर आपका है।"},{"strong":"तकनीकी लॉग:","text":"हम ऐसी प्रणालियाँ कॉन्फ़िगर करते हैं कि IP पता या डिवाइस पहचानकर्ता अस्थायी प्रसंस्करण से अधिक संग्रहीत न हों। यदि सुरक्षा या प्रदर्शन के लिए न्यूनतम इन्फ्रास्ट्रक्चर लॉग उत्पन्न होते हैं, तो उन्हें आपके उत्तरों से नहीं जोड़ा जाता और संस्थागत नीति के अनुसार हटा दिए जाते हैं।","className":"sub-point"},{"strong":"सुरक्षा:","text":"डेटा सुरक्षित, एक्सेस-नियंत्रित प्रणालियों पर संग्रहीत किया जाता है जिनमें एन्क्रिप्शन और भूमिका-आधारित एक्सेस नियंत्रण जैसे उचित तकनीकी और संगठनात्मक उपाय शामिल हैं।","className":"sub-point"}]},{"heading":"8) डेटा उपयोग, साझा करना और संरक्षण","paragraphs":[{"strong":"उद्देश्य सीमितता:","text":"डेटा का उपयोग केवल स्तन कैंसर जोखिम कारकों और मॉडल विकास/मान्यता पर अकादमिक अनुसंधान के लिए किया जाएगा।","className":"sub-point"},{"strong":"साझाकरण:","text":"केवल डी-आईडेंटिफाइड या समेकित डेटासेट अनुसंधान सहयोगियों और शैक्षणिक भागीदारों के साथ समान उद्देश्य के लिए साझा किए जा सकते हैं। प्रकाशन ऐसे समेकित परिणामों की रिपोर्ट करेंगे जो व्यक्तियों की पहचान नहीं करते।","className":"sub-point"},{"strong":"संरक्षण:","text":"गुमनाम डेटासेट पुनरुत्पादन और ऑडिट के लिए संस्थागत/आईईसी नीति के अनुसार रखे जा सकते हैं।","className":"sub-point"}]},{"heading":"9) लागत और प्रतिपूर्ति","paragraphs":[{"text":"भाग लेने के लिए आपको कोई लागत नहीं है, और आपको कोई भुगतान नहीं किया जाएगा। यह न्यूनतम-जोखिम, केवल सर्वेक्षण अध्ययन होने के कारण चोट के लिए कोई प्रतिपूर्ति उपलब्ध नहीं है।"}]},{"heading":"10) संपर्क जानकारी","paragraphs":[{"text":"यदि आप अध्ययन से स्वतंत्र किसी व्यक्ति से बात करना चाहते हैं, तो आप संपर्क कर सकते हैं:"},{"strong":"संस्थागत नैतिकता समिति (IEC)","text":""},{"strong":"नाम:","text":"डॉ. श्री विद्या जगदीश, सचिव, आईईसी, टीएएनयूएच (Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH)"},{"strong":"ईमेल:","text":"secretary.iec@tanuh.ai"},{"strong":"फोन#","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"स्वीकार करें और आगे बढ़ें"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'kn','{"title":"ಅಧ್ಯಯನದ ಬಗ್ಗೆ ಭಾಗವಹಿಸುವವರ ಮಾಹಿತಿ","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"ಅಧ್ಯಯನ ಶೀರ್ಷಿಕೆ","sponsor":"ಪ್ರಾಯೋಜಕ","iecApproval":"ಐಇಸಿ ಅನುಮೋದನೆ"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) ಆಹ್ವಾನ ಮತ್ತು ಸ್ವಯಂಪ್ರೇರಿತ ಭಾಗವಹಿಸುವಿಕೆ","paragraphs":[{"text":"ನೀವು ಭಾರತೀಯ ಜನಸಂಖ್ಯೆಯಲ್ಲಿನ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಅಂಶಗಳ ಬಗ್ಗೆ ಸಂಶೋಧನಾ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಲು ಆಹ್ವಾನಿತರಾಗಿದ್ದೀರಿ. ಭಾಗವಹಿಸುವಿಕೆ ಸಂಪೂರ್ಣವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿದೆ. ನೀವು ಯಾವುದೇ ದಂಡ ಅಥವಾ ಲಾಭ ನಷ್ಟವಿಲ್ಲದೆ ಭಾಗವಹಿಸಲು ನಿರಾಕರಿಸಬಹುದು."},{"strong":"ಅರ್ಹತೆ:","text":"ನೀವು 18 ವರ್ಷ ಅಥವಾ ಹೆಚ್ಚು ವಯಸ್ಸಿನವರಾಗಿರಬೇಕು. ನೀವು 18 ವರ್ಷಕ್ಕಿಂತ ಕಡಿಮೆ ವಯಸ್ಸಿನವರಾದರೆ, ದಯವಿಟ್ಟು ಮುಂದುವರೆಯಬೇಡಿ.","className":"sub-point"}]},{"heading":"2) ಅಧ್ಯಯನದ ಉದ್ದೇಶ","paragraphs":[{"text":"ನಾವು ಸಮೀಕ್ಷೆಯ ಪ್ರತಿಕ್ರಿಯೆಗಳನ್ನು ವಿಶ್ಲೇಷಿಸಿ ಭಾರತದಲ್ಲಿ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಅಂಶಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಮತ್ತು 5 ವರ್ಷದ ಮತ್ತು ಜೀವಮಾನ ಅಪಾಯವನ್ನು ಅಂದಾಜಿಸುವ ಸಂಶೋಧನೆಗಾಗಿ ಮಾತ್ರವಾದ ಮಾದರಿಯನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸುತ್ತೇವೆ. ಈ ಸಾಧನವು ಅಭಿವೃದ್ಧಿಯಲ್ಲಿದೆ, ವೈದ್ಯಕೀಯ ಬಳಕೆಗೆ ಅಲ್ಲ ಮತ್ತು ಯಾವುದೇ ವೈದ್ಯಕೀಯ ನಿರ್ಣಯ ಅಥವಾ ಚಿಕಿತ್ಸೆಯನ್ನು ನೀಡುವುದಿಲ್ಲ."}]},{"heading":"3) ನೀವು ಏನು ಮಾಡಬೇಕು","paragraphs":[{"text":"ಜನಸಾಂಖ್ಯಿಕ ಮತ್ತು ಆರೋಗ್ಯ ಸಂಬಂಧಿತ ಅಂಶಗಳ ಕುರಿತು ಒಂದೇ ಬಾರಿಗೆ ಪ್ರಶ್ನಾವಳಿಯನ್ನು ಭರ್ತಿ ಮಾಡಿ. ಅಂದಾಜು ಸಮಯವು ಸುಮಾರು 5-7 ನಿಮಿಷಗಳು. ನೀವು ಅಸೌಕರ್ಯಕರವೆಂದು ಭಾವಿಸಿದ ಯಾವುದೇ ಪ್ರಶ್ನೆಯನ್ನು ಬಿಟ್ಟುಬಿಡಬಹುದು."}]},{"heading":"4) ಅಪಾಯಗಳು ಮತ್ತು ಅಸೌಕರ್ಯಗಳು","paragraphs":[{"text":"ಅಪಾಯಗಳು ಅತಿ ಕಡಿಮೆ ಮತ್ತು ವೈಯಕ್ತಿಕ ಪ್ರಶ್ನೆಗಳ ಅಸೌಕರ್ಯವನ್ನು ಒಳಗೊಂಡಿರಬಹುದು. \\"ಡೇಟಾ ಮತ್ತು ಗೌಪ್ಯತೆ\\" ವಿಭಾಗದಲ್ಲಿ ವಿವರಿಸಿರುವ ಭದ್ರತಾ ಕ್ರಮಗಳಿದ್ದರೂ ಡೇಟಾ ಉಲ್ಲಂಘನೆಯ ಸಣ್ಣ ಅಪಾಯವಿದೆ."}]},{"heading":"5) ಪ್ರಯೋಜನಗಳು","paragraphs":[{"text":"ನಿಮಗೆ ನೇರ ಪ್ರಯೋಜನ ಇರುವುದಿಲ್ಲ. ಈ ಅಧ್ಯಯನದ ಫಲಿತಾಂಶಗಳು ಭಾರತದಲ್ಲಿ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಅಂಶಗಳ ಅರಿವು ಹೆಚ್ಚಿಸಲು ಮತ್ತು ಭವಿಷ್ಯದ ಸಂಶೋಧನಾ ಸಾಧನಗಳ ಅಭಿವೃದ್ಧಿಗೆ ಸಹಾಯ ಮಾಡಬಹುದು."}]},{"heading":"6) ಮುಖ್ಯವಾದುದು: ಸಂಶೋಧನೆಗಾಗಿ ಮಾತ್ರ; ವೈದ್ಯಕೀಯ ಸಲಹೆ ಅಲ್ಲ","className":"important-notice","paragraphs":[{"text":"ಈ ಸಾಧನದಿಂದ ದೊರಕುವ ಯಾವುದೇ ಅಂಕ ಅಥವಾ ಫಲಿತಾಂಶವು ಸಂಶೋಧನೆಗಾಗಿ ಮಾತ್ರ. ಇದು ವೃತ್ತಿಪರ ವೈದ್ಯಕೀಯ ಸಲಹೆ, ನಿರ್ಣಯ ಅಥವಾ ಚಿಕಿತ್ಸೆಗೆ ಪರ್ಯಾಯವಲ್ಲ. ಈ ಸಾಧನವು CDSCO ಯಿಂದ ಅನುಮೋದಿಸಲ್ಪಟ್ಟಿಲ್ಲ ಮತ್ತು Software as a Medical Device (SaMD) ಆಗಿ ಪ್ರಮಾಣೀಕರಿಸಲ್ಪಟ್ಟಿಲ್ಲ. ಯಾವುದೇ ಆರೋಗ್ಯ ಸಮಸ್ಯೆಗಳಿಗೆ ದಯವಿಟ್ಟು ಅರ್ಹ ವೈದ್ಯರನ್ನು ಸಂಪರ್ಕಿಸಿ."}]},{"heading":"7) ಡೇಟಾ ಮತ್ತು ಗೌಪ್ಯತೆ (ಅನಾಮಧೇಯ ಸಮೀಕ್ಷೆ)","paragraphs":[{"text":"ನಾವು ಯಾವುದೇ ವೈಯಕ್ತಿಕ ಗುರುತುಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ (ಹೆಸರು, ಫೋನ್, ಇಮೇಲ್, ವಿಳಾಸ, ರಾಷ್ಟ್ರೀಯ ಐಡಿ ಇತ್ಯಾದಿ). ಪ್ರತಿಕ್ರಿಯೆಗಳು ನಿಮ್ಮ ಗುರುತಿಗೆ ಯಾವುದೇ ಸಂಪರ್ಕವಿಲ್ಲದೆ ದಾಖಲಿಸಲಾಗುತ್ತದೆ. ಏಕೆಂದರೆ ಪ್ರತಿಕ್ರಿಯೆಗಳು ಅನಾಮಧೇಯವಾಗಿವೆ, ನೀವು ಸಲ್ಲಿಸಿದ ನಂತರ ಅವುಗಳನ್ನು ಹಿಂಪಡೆಯಲು ಅಥವಾ ಅಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ."},{"strong":"ತಾಂತ್ರಿಕ ದಾಖಲೆಗಳು:","text":"ನಾವು IP ವಿಳಾಸಗಳು ಅಥವಾ ಸಾಧನ ಗುರುತುಗಳನ್ನು ಸಂಗ್ರಹಿಸುವುದನ್ನು ತಪ್ಪಿಸಲು ವ್ಯವಸ್ಥೆಗಳನ್ನು ಸಂರಚಿಸುತ್ತೇವೆ. ಭದ್ರತೆ ಅಥವಾ ಕಾರ್ಯಕ್ಷಮತೆಗಾಗಿ ಸೃಷ್ಟಿಯಾಗುವ ಕನಿಷ್ಠ ಮೂಲಸೌಕರ್ಯ ದಾಖಲೆಗಳು ನಿಮ್ಮ ಪ್ರತಿಕ್ರಿಯೆಗಳೊಂದಿಗೆ ಸಂಪರ್ಕಿಸಲ್ಪಟ್ಟಿಲ್ಲ ಮತ್ತು ಅವು ಸಂಸ್ಥೆಯ ನೀತಿಯ ಪ್ರಕಾರ ಅಳಿಸಲಾಗುತ್ತದೆ.","className":"sub-point"},{"strong":"ಭದ್ರತೆ:","text":"ಡೇಟಾವನ್ನು ಭದ್ರ, ಪ್ರವೇಶ ನಿಯಂತ್ರಿತ ವ್ಯವಸ್ಥೆಗಳಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ, ಎನ್ಕ್ರಿಪ್ಷನ್ ಮತ್ತು ಪಾತ್ರಾಧಾರಿತ ಪ್ರವೇಶ ನಿಯಂತ್ರಣಗಳಂತಹ ತಾಂತ್ರಿಕ ಮತ್ತು ಸಂಘಟನಾ ಕ್ರಮಗಳೊಂದಿಗೆ.","className":"sub-point"}]},{"heading":"8) ಡೇಟಾ ಬಳಕೆ, ಹಂಚಿಕೆ ಮತ್ತು ಸಂಗ್ರಹಣೆ","paragraphs":[{"strong":"ಉದ್ದೇಶದ ಮಿತಿ:","text":"ಡೇಟಾವನ್ನು ಶೈಕ್ಷಣಿಕ ಸಂಶೋಧನೆಗಾಗಿ ಮಾತ್ರ, ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಅಂಶಗಳು ಮತ್ತು ಮಾದರಿ ಅಭಿವೃದ್ಧಿ/ಮಾನ್ಯತೆಗಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ.","className":"sub-point"},{"strong":"ಹಂಚಿಕೆ:","text":"ಗುರುತಿಸಲಾಗದ ಅಥವಾ ಸಂಗ್ರಹಿತ ಡೇಟಾಸೆಟ್‌ಗಳನ್ನು ಸಂಶೋಧನಾ ಸಹಯೋಗಿಗಳು ಮತ್ತು ಶೈಕ್ಷಣಿಕ ಪಾಲುದಾರರೊಂದಿಗೆ ಅದೇ ಉದ್ದೇಶಕ್ಕಾಗಿ ಹಂಚಬಹುದು. ಪ್ರಕಟಣೆಗಳು ವ್ಯಕ್ತಿಗಳನ್ನು ಗುರುತಿಸದ ಒಟ್ಟಾರೆ ಫಲಿತಾಂಶಗಳನ್ನು ಮಾತ್ರ ವರದಿ ಮಾಡುತ್ತವೆ.","className":"sub-point"},{"strong":"ಸಂಗ್ರಹಣೆ:","text":"ಅನಾಮಧೇಯ ಡೇಟಾಸೆಟ್‌ಗಳನ್ನು ಪುನರುತ್ಪಾದನೆ ಮತ್ತು ಪರಿಶೀಲನೆಗಾಗಿ ಸಂಸ್ಥೆಯ/ಐಇಸಿ ನೀತಿಯ ಪ್ರಕಾರ ಉಳಿಸಬಹುದು.","className":"sub-point"}]},{"heading":"9) ವೆಚ್ಚ ಮತ್ತು ಪರಿಹಾರ","paragraphs":[{"text":"ನೀವು ಭಾಗವಹಿಸಲು ಯಾವುದೇ ವೆಚ್ಚವಿಲ್ಲ, ಮತ್ತು ನಿಮಗೆ ಯಾವುದೇ ಪಾವತಿ ನೀಡಲಾಗುವುದಿಲ್ಲ. ಇದು ಕನಿಷ್ಠ ಅಪಾಯದ ಸಮೀಕ್ಷಾ ಅಧ್ಯಯನವಾಗಿರುವುದರಿಂದ ಗಾಯಕ್ಕೆ ಪರಿಹಾರ ಲಭ್ಯವಿಲ್ಲ."}]},{"heading":"10) ಸಂಪರ್ಕ ಮಾಹಿತಿ (Contact Information)","paragraphs":[{"text":"ನೀವು ಅಧ್ಯಯನದಿಂದ ಸ್ವತಂತ್ರವಾಗಿರುವ ಯಾರೊಂದಿಗಾದರೂ ಮಾತನಾಡಲು ಬಯಸಿದರೆ, ನೀವು ಇವರನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು:"},{"strong":"ಸಂಸ್ಥೆಯ ನೈತಿಕ ಸಮಿತಿ (IEC)","text":""},{"strong":"ಹೆಸರು (Name):","text":"Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH"},{"strong":"ಇಮೇಲ್ (Email):","text":"secretary.iec@tanuh.ai"},{"strong":"ಫೋನ್ (Phone#):","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"ಸ್ವೀಕರಿಸಿ ಮತ್ತು ಮುಂದುವರಿಯಿರಿ"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'ml','{"title":"പഠനത്തെക്കുറിച്ചുള്ള പങ്കാളി വിവരങ്ങൾ","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"അധ്യയന ശീർഷകം","sponsor":"സ്പോൺസർ","iecApproval":"IEC അംഗീകാരം"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) ക്ഷണം & സ്വമേധയാ പങ്കാളിത്തം","paragraphs":[{"text":"ഇന്ത്യൻ ജനസംഖ്യയിലെ സ്തനാർബുദ അപകടഘടകങ്ങളെക്കുറിച്ചുള്ള ഒരു ഗവേഷണ പഠനത്തിൽ പങ്കെടുക്കാൻ നിങ്ങളെ ക്ഷണിക്കുന്നു. പങ്കാളിത്തം പൂർണ്ണമായും സ്വമേധയാ ആണ്. നിങ്ങൾ പങ്കെടുക്കാതിരിക്കാൻ തിരഞ്ഞെടുക്കാമെന്നും അതിനാൽ നിങ്ങൾക്ക് യാതൊരു നഷ്ടവുമുണ്ടാകില്ല."},{"strong":"അർഹത:","text":"നിങ്ങൾക്ക് കുറഞ്ഞത് 18 വയസ്സ് ആയിരിക്കണം. 18 വയസ്സിനു താഴെയാണെങ്കിൽ ദയവായി തുടരരുത്.","className":"sub-point"}]},{"heading":"2) പഠനത്തിന്റെ ഉദ്ദേശ്യം","paragraphs":[{"text":"ഇന്ത്യയിലെ സ്തനാർബുദ അപകടഘടകങ്ങളെ മനസ്സിലാക്കുന്നതിനും 5 വർഷവും ജീവിതകാല അപകടവും കണക്കാക്കുന്നതിനുള്ള ഗവേഷണ മാതൃക വികസിപ്പിക്കുന്നതിനുമായി സർവേ മറുപടികൾ ഞങ്ങൾ വിശകലനം ചെയ്യും. ഈ ഉപകരണം വികസന ഘട്ടത്തിലാണ്, ഇത് ചികിത്സയ്ക്കോ രോഗനിർണയത്തിനോ വേണ്ടിയല്ല."}]},{"heading":"3) നിങ്ങൾ ചെയ്യേണ്ടത്","paragraphs":[{"text":"ജനസാംഖ്യാ വിവരങ്ങളും ആരോഗ്യവുമായി ബന്ധപ്പെട്ട ഘടകങ്ങളും ഉൾപ്പെടുന്ന ഒരു തവണ മാത്രം ചോദനപ്പത്രം പൂരിപ്പിക്കുക. കണക്കാക്കിയ സമയം ഏകദേശം 5–7 മിനിറ്റ് ആണ്. നിങ്ങൾക്ക് അസൗകര്യമുള്ള ചോദ്യങ്ങൾ ഒഴിവാക്കാം."}]},{"heading":"4) അപകടങ്ങളും അസൗകര്യങ്ങളും","paragraphs":[{"text":"അപകടസാധ്യത വളരെ കുറവാണ്, എന്നാൽ ചില വ്യക്തിപരമായ ചോദ്യങ്ങൾ നിങ്ങളെ അസ്വസ്ഥരാക്കാം. \\"ഡാറ്റയും സ്വകാര്യതയും\\" എന്ന വിഭാഗത്തിൽ പറയുന്ന സുരക്ഷാ നടപടികൾ വഴി ഡാറ്റ ചോർച്ചയുടെ അപകടം കുറയ്ക്കുന്നു."}]},{"heading":"5) പ്രയോജനങ്ങൾ","paragraphs":[{"text":"നിങ്ങൾക്ക് നേരിട്ടുള്ള പ്രയോജനം ഉണ്ടാകണമെന്നില്ല. കണ്ടെത്തലുകൾ ഇന്ത്യയിലെ സ്തനാർബുദ അപകടഘടകങ്ങളെക്കുറിച്ചുള്ള ധാരണ മെച്ചപ്പെടുത്താനും ഭാവിയിലെ ഗവേഷണ ഉപകരണങ്ങൾ വികസിപ്പിക്കാനുമുള്ള മാർഗ്ഗനിർദ്ദേശം നൽകാനും സഹായിക്കും."}]},{"heading":"6) പ്രധാനപ്പെട്ടത്: ഗവേഷണത്തിനായുള്ളതേ ഉള്ളൂ; മെഡിക്കൽ ഉപദേശം അല്ല","className":"important-notice","paragraphs":[{"text":"ഈ ഉപകരണം നൽകുന്ന സ്കോർ അല്ലെങ്കിൽ ഫലം ഗവേഷണ ആവശ്യങ്ങൾക്കായി മാത്രമാണ്. ഇത് പ്രൊഫഷണൽ മെഡിക്കൽ ഉപദേശം, രോഗനിർണയം അല്ലെങ്കിൽ ചികിത്സയ്ക്ക് പകരം വരില്ല. ഈ ഉപകരണം CDSCO യാൽ അംഗീകൃതമല്ല, ഇത് മെഡിക്കൽ ഉപകരണമായി (SaMD) സർട്ടിഫൈ ചെയ്തതുമല്ല. നിങ്ങളുടെ ആരോഗ്യ പ്രശ്നങ്ങൾക്ക് ദയവായി യോഗ്യരായ ഡോക്ടറെ സമീപിക്കുക."}]},{"heading":"7) ഡാറ്റയും സ്വകാര്യതയും (അജ്ഞാത സർവേ)","paragraphs":[{"text":"ഞങ്ങൾ യാതൊരു വ്യക്തിഗത തിരിച്ചറിയൽ വിവരങ്ങളും (പേര്, ഫോൺ, ഇമെയിൽ, വിലാസം, ഐഡി മുതലായവ) ശേഖരിക്കുന്നില്ല. മറുപടികൾ നിങ്ങളുടെ തിരിച്ചറിയലുമായി ബന്ധമില്ലാതെ രേഖപ്പെടുത്തപ്പെടുന്നു. സമർപ്പിച്ചതിന് ശേഷം നിങ്ങളുടെ മറുപടികൾ പിൻവലിക്കാനോ ഇല്ലാതാക്കാനോ സാധിക്കില്ല, കാരണം അവയെ ഞങ്ങൾ തിരിച്ചറിയാൻ കഴിയില്ല."},{"strong":"സാങ്കേതിക രേഖകൾ:","text":"ഐ.പി. വിലാസങ്ങൾ അല്ലെങ്കിൽ ഉപകരണ ഐഡികൾ താൽക്കാലിക പ്രോസസ്സിംഗ് കഴിഞ്ഞാൽ സൂക്ഷിക്കാത്ത രീതിയിൽ സിസ്റ്റങ്ങൾ ക്രമീകരിച്ചിരിക്കുന്നു. സുരക്ഷയ്ക്കോ പ്രകടനത്തിനോ വേണ്ടി കുറച്ച് ലോഗുകൾ സൃഷ്ടിക്കപ്പെട്ടാലും, അവ നിങ്ങളുടെ മറുപടികളുമായി ബന്ധിപ്പിക്കില്ല, സ്ഥാപന നയപ്രകാരം അവ നീക്കം ചെയ്യും.","className":"sub-point"},{"strong":"സുരക്ഷ:","text":"ഡാറ്റ സുരക്ഷിതമായ, ആക്സസ് നിയന്ത്രിതമായ സിസ്റ്റങ്ങളിൽ സൂക്ഷിക്കുന്നു, എൻക്രിപ്ഷൻ, റോൾ അടിസ്ഥാനമാക്കിയ ആക്സസ് നിയന്ത്രണം തുടങ്ങിയ അനുയോജ്യമായ സാങ്കേതികവും സംഘടനാത്മകവുമായ നടപടികളോടുകൂടി.","className":"sub-point"}]},{"heading":"8) ഡാറ്റയുടെ ഉപയോഗം, പങ്കിടൽ, സംരക്ഷണം","paragraphs":[{"strong":"ഉദ്ദേശപരിധി:","text":"ഡാറ്റ സ്തനാർബുദ അപകടഘടകങ്ങളും മാതൃക വികസനവും സംബന്ധിച്ച അക്കാദമിക് ഗവേഷണത്തിനായി മാത്രം ഉപയോഗിക്കും.","className":"sub-point"},{"strong":"പങ്കിടൽ:","text":"തിരിച്ചറിയാൻ കഴിയാത്ത അല്ലെങ്കിൽ സംഗ്രഹിച്ച ഡാറ്റാസെറ്റുകൾ മാത്രമേ ഗവേഷണ സഹപ്രവർത്തകരുമായും അക്കാദമിക് പങ്കാളികളുമായും പങ്കിടുകയുള്ളു. പ്രസിദ്ധീകരണങ്ങൾ വ്യക്തികളെ തിരിച്ചറിയാത്ത ആകെയുള്ള ഫലങ്ങൾ മാത്രമേ റിപ്പോർട്ട് ചെയ്യുകയുള്ളു.","className":"sub-point"},{"strong":"സംരക്ഷണം:","text":"അജ്ഞാത ഡാറ്റാസെറ്റുകൾ സ്ഥാപനം/IEC നയം അനുസരിച്ച് പുനരാവർത്തനത്തിനും ഓഡിറ്റിനുമായി സൂക്ഷിച്ചേക്കാം.","className":"sub-point"}]},{"heading":"9) ചെലവും പ്രതിഫലവും","paragraphs":[{"text":"പങ്കെടുക്കുന്നതിനായി നിങ്ങളിൽ നിന്ന് യാതൊരു ചെലവും ഈടാക്കില്ല, കൂടാതെ നിങ്ങൾക്ക് പ്രതിഫലവും ലഭിക്കില്ല. ഇത് കുറഞ്ഞ അപകടസാധ്യതയുള്ള സർവേ പഠനമായതിനാൽ പരിക്കുകൾക്കുള്ള നഷ്ടപരിഹാരം ലഭ്യമല്ല."}]},{"heading":"10) ബന്ധപ്പെടാനുള്ള വിവരങ്ങൾ (Contact Information)","paragraphs":[{"text":"പഠനവുമായി ബന്ധമില്ലാത്ത ഒരാളോട് സംസാരിക്കാൻ നിങ്ങൾ ആഗ്രഹിക്കുന്നുവെങ്കിൽ, നിങ്ങൾക്ക് ഇവരെയുമായി ബന്ധപ്പെടാം:"},{"strong":"ഇൻസ്റ്റിറ്റ്യൂഷണൽ എത്തിക്‌സ് കമ്മിറ്റി (IEC)","text":""},{"strong":"പേര് (Name):","text":"Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH"},{"strong":"ഇമെയിൽ (Email):","text":"secretary.iec@tanuh.ai"},{"strong":"ഫോൺ (Phone#):","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"സ്വീകരിക്കുക & തുടരുക"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'mr','{"title":"अभ्यासाबद्दल सहभागी माहिती","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"अभ्यास शीर्षक","sponsor":"प्रायोजक","iecApproval":"IEC मान्यता"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) आमंत्रण आणि स्वेच्छा सहभाग","paragraphs":[{"text":"भारतीय लोकसंख्येमध्ये स्तनाच्या कर्करोगाच्या जोखीम घटकांवरील संशोधन अभ्यासामध्ये सहभागी होण्यासाठी आपण आमंत्रित आहात. सहभाग पूर्णपणे स्वेच्छेने आहे. सहभागी न होण्याचा निर्णय घेतल्यास तुम्हाला कोणताही दंड किंवा लाभ गमवावा लागणार नाही."},{"strong":"पात्रता:","text":"तुमचे वय 18 वर्षे किंवा त्याहून अधिक असणे आवश्यक आहे. जर तुमचे वय 18 वर्षांपेक्षा कमी असेल, तर कृपया पुढे जाऊ नका.","className":"sub-point"}]},{"heading":"2) अभ्यासाचा उद्देश","paragraphs":[{"text":"आम्ही सर्वेक्षणाच्या प्रतिसादांचे विश्लेषण करून भारतातील स्तनाच्या कर्करोगाच्या जोखीम घटकांचा अभ्यास करू आणि संशोधनासाठी वापरले जाणारे असे मॉडेल विकसित करू जे 5 वर्षे आणि आजीवन जोखीम अंदाज करेल. हे साधन अद्याप विकासाच्या टप्प्यात आहे, वैद्यकीय वापरासाठी नाही आणि कोणतेही वैद्यकीय निदान किंवा उपचार प्रदान करत नाही."}]},{"heading":"3) आपण काय कराल","paragraphs":[{"text":"लोकसंख्याशास्त्रीय आणि आरोग्याशी संबंधित घटकांवरील एकदाच भरायचे प्रश्नावली पूर्ण करा. अंदाजे वेळ 5–7 मिनिटे आहे. तुम्हाला अस्वस्थ वाटणारे कोणतेही प्रश्न वगळू शकता."}]},{"heading":"4) जोखीम आणि असुविधा","paragraphs":[{"text":"जोखीम अत्यंत कमी आहेत आणि वैयक्तिक प्रश्नांमुळे काही असुविधा होऊ शकते. डेटाशी संबंधित कोणतीही जोखीम ''डेटा आणि गोपनीयता'' या विभागात वर्णन केलेल्या सुरक्षेच्या उपाययोजनांद्वारे कमी केली जाते."}]},{"heading":"5) फायदे","paragraphs":[{"text":"आपल्याला थेट काहीही लाभ होणार नाही. या निष्कर्षांमुळे भारतातील स्तनाच्या कर्करोगाच्या जोखीम घटकांविषयी अधिक चांगले समज प्राप्त होईल आणि भविष्यातील संशोधन साधनांच्या विकासाला मदत होऊ शकते."}]},{"heading":"6) महत्त्वाचे: संशोधनासाठीच; वैद्यकीय सल्ला नाही","className":"important-notice","paragraphs":[{"text":"या साधनातून मिळणारा कोणताही गुण किंवा निकाल केवळ संशोधनासाठीच आहे. हे व्यावसायिक वैद्यकीय सल्ला, निदान किंवा उपचार यांचा पर्याय नाही. हे साधन CDSCO कडून मान्यताप्राप्त नाही आणि प्रमाणित Software as a Medical Device (SaMD) नाही. आरोग्याशी संबंधित कोणत्याही चिंतेसाठी कृपया पात्र डॉक्टरांचा सल्ला घ्या."}]},{"heading":"7) डेटा आणि गोपनीयता (अनामिक सर्वेक्षण)","paragraphs":[{"text":"आम्ही कोणतीही वैयक्तिक ओळख (उदा., नाव, फोन, ईमेल, अचूक पत्ता, राष्ट्रीय ओळख क्रमांक) गोळा करत नाही. प्रतिसाद तुमच्या ओळखीशी कोणताही दुवा न ठेवता नोंदवले जातात. कारण हे सबमिशन अनामिक आहेत, एकदा सबमिट केल्यानंतर आम्ही तुमचे प्रतिसाद मागे घेऊ किंवा हटवू शकत नाही."},{"strong":"तांत्रिक नोंदी:","text":"आम्ही IP पत्ते किंवा डिव्हाइस ओळखकर्ता साठवला जाणार नाही याची खात्री करण्यासाठी प्रणाली कॉन्फिगर करतो. सुरक्षा किंवा कार्यक्षमतेसाठी जर काही अल्पकालीन लॉग तयार झाले, तर ते तुमच्या प्रतिसादांशी जोडलेले नसतात आणि संस्थात्मक धोरणानुसार हटवले जातात.","className":"sub-point"},{"strong":"सुरक्षा:","text":"डेटा सुरक्षित आणि नियंत्रित प्रवेश प्रणालींमध्ये साठवला जातो ज्यात एन्क्रिप्शन आणि भूमिका-आधारित प्रवेश नियंत्रणासारख्या तांत्रिक आणि संघटनात्मक उपायांचा वापर केला जातो.","className":"sub-point"}]},{"heading":"8) डेटा वापर, सामायिकरण आणि साठवण","paragraphs":[{"strong":"उद्देश मर्यादा:","text":"डेटा केवळ शैक्षणिक संशोधनासाठी, विशेषतः स्तनाच्या कर्करोगाच्या जोखीम घटकांच्या अभ्यासासाठी आणि मॉडेल विकास/प्रमाणनासाठी वापरला जाईल.","className":"sub-point"},{"strong":"सामायिकरण:","text":"फक्त ओळख हटवलेले किंवा एकत्रित डेटासेट्स संशोधन सहयोगी आणि शैक्षणिक भागीदारांसह समान उद्देशासाठी सामायिक केले जाऊ शकतात. प्रकाशनांमध्ये वैयक्तिक ओळख उघड न करणारे एकत्रित निकाल अहवालित केले जातील.","className":"sub-point"},{"strong":"साठवण:","text":"अनामिक डेटासेट्स संस्थात्मक/IEC धोरणानुसार पुनरुत्पादकता आणि ऑडिटसाठी ठेवले जाऊ शकतात.","className":"sub-point"}]},{"heading":"9) खर्च आणि मोबदला","paragraphs":[{"text":"या अभ्यासात सहभागी होण्यासाठी तुम्हाला कोणताही खर्च नाही आणि तुम्हाला कोणतेही मानधन मिळणार नाही. हा कमी-जोखमीचा सर्वेक्षण अभ्यास असल्याने, जखमेबद्दल कोणताही मोबदला उपलब्ध नाही."}]},{"heading":"10) संपर्क माहिती (Contact Information)","paragraphs":[{"text":"तुम्ही अभ्यासापेक्षा स्वतंत्र असलेल्या कोणाशी बोलू इच्छित असल्यास, तुम्ही यांच्याशी संपर्क साधू शकता:"},{"strong":"संस्थात्मक नैतिकता समिती (IEC)","text":""},{"strong":"नाव (Name):","text":"Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH"},{"strong":"ईमेल (Email):","text":"secretary.iec@tanuh.ai"},{"strong":"फोन (Phone#):","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"स्वीकारा आणि पुढे जा"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'or','{"title":"ଅଧ୍ୟୟନ ବିଷୟରେ ଅଂଶଗ୍ରହଣକାରୀ ତଥ୍ୟ","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"ଅଧ୍ୟୟନ ଶିରୋନାମ","sponsor":"ପ୍ରଯୋଜକ","iecApproval":"IEC ଅନୁମୋଦନ"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) ଆମନ୍ତ୍ରଣ ଏବଂ ସ୍ୱଇଚ୍ଛାପୂର୍ଣ୍ଣ ଅଂଶଗ୍ରହଣ","paragraphs":[{"text":"ଆପଣଙ୍କୁ ଭାରତୀୟ ଜନସଂଖ୍ୟାରେ ସ୍ତନ କ୍ୟାନ୍ସର ଝୁମୁକ କାରକ ବିଷୟରେ ଏକ ଗବେଷଣା ଅଧ୍ୟୟନରେ ଅଂଶଗ୍ରହଣ କରିବାକୁ ଆମନ୍ତ୍ରଣ ଦିଆଯାଉଛି। ଅଂଶଗ୍ରହଣ ସମ୍ପୂର୍ଣ୍ଣ ସ୍ୱଇଚ୍ଛାପୂର୍ଣ୍ଣ ଅଟେ। ଆପଣ ଚାହିଲେ ଅଂଶଗ୍ରହଣ ନକରିପାରିବେ ଏବଂ ଏହା ପାଇଁ କୌଣସି ଦଣ୍ଡ ବା ଲାଭ ହାନି ହେବ ନାହିଁ।"},{"strong":"ଯୋଗ୍ୟତା:","text":"ଆପଣଙ୍କୁ 18 ବର୍ଷ ବା ତାହାରୁ ଅଧିକ ବୟସ୍ସ ହେବା ଦରକାର। ଯଦି ଆପଣଙ୍କ ବୟସ 18 ବର୍ଷ ଠାରୁ କମ୍, ଦୟାକରି ଆଗକୁ ଯିବେ ନାହିଁ।","className":"sub-point"}]},{"heading":"2) ଅଧ୍ୟୟନର ଉଦ୍ଦେଶ୍ୟ","paragraphs":[{"text":"ଆମେ ସର୍ବେ ଉତ୍ତରଗୁଡ଼ିକୁ ବିଶ୍ଳେଷଣ କରିବା ମାଧ୍ୟମରେ ଭାରତରେ ସ୍ତନ କ୍ୟାନ୍ସର ଝୁମୁକ କାରକଗୁଡ଼ିକୁ ବୁଝିବା ଏବଂ 5 ବର୍ଷ ଓ ଜୀବନକାଳୀନ ଝୁମୁକ ଆନୁମାନିକ କରିବା ପାଇଁ ଗବେଷଣା ମଡେଲ ତିଆରି କରିବା ଉଦ୍ଦେଶ୍ୟରେ କାମ କରିବୁ। ଏହା ଏକ ଗବେଷଣା ଉପକରଣ ଅଟେ, ମେଡିକାଲ ଉପଯୋଗ ପାଇଁ ନୁହେଁ ଏବଂ କୌଣସି ଚିକିତ୍ସା ବା ନିଦାନ ଦେଉନାହିଁ।"}]},{"heading":"3) ଆପଣ କଣ କରିବେ","paragraphs":[{"text":"ଲୋକସଂଖ୍ୟାତମକ ଏବଂ ସ୍ୱାସ୍ଥ୍ୟ ସମ୍ପର୍କିତ ତଥ୍ୟ ଉପରେ ଏକଥର ନିର୍ଦ୍ଧାରିତ ପ୍ରଶ୍ନାବଳୀ ପୂରଣ କରନ୍ତୁ। ଅନୁମାନିତ ସମୟ 5-7 ମିନିଟ୍ ଅଟେ। ଯେଉଁ ପ୍ରଶ୍ନର ଉତ୍ତର ଦେବାରେ ଅସୁବିଧା ଲାଗେ, ତାହା ଛାଡ଼ି ଦିଅନ୍ତୁ।"}]},{"heading":"4) ଝୁମୁକ ଏବଂ ଅସୁବିଧା","paragraphs":[{"text":"ଝୁମୁକ ଅତ୍ୟଳ୍ପ ଅଟେ, କିନ୍ତୁ କେତେକ ପ୍ରଶ୍ନ ବ୍ୟକ୍ତିଗତ ଭାବରେ ଅସୁବିଧାକାରୀ ହୋଇପାରେ। ''ଡାଟା ଏବଂ ଗୋପନୀୟତା'' ଅଂଶରେ ଉଲ୍ଲେଖିତ ସୁରକ୍ଷା ବ୍ୟବସ୍ଥା ଡାଟା ତ୍ରୁଟିର ଝୁମୁକକୁ ହ୍ରାସ କରେ।"}]},{"heading":"5) ଲାଭ","paragraphs":[{"text":"ଆପଣଙ୍କୁ ସିଧାସଳଖ ଲାଭ ନ ମିଳିପାରେ। ଏହି ଅଧ୍ୟୟନ ଭାରତରେ ସ୍ତନ କ୍ୟାନ୍ସର ଝୁମୁକ କାରକଗୁଡ଼ିକୁ ବୁଝିବା ଓ ଭବିଷ୍ୟତ ଗବେଷଣା ଉପକରଣ ତିଆରି କରିବାରେ ସହାୟକ ହୋଇପାରେ।"}]},{"heading":"6) ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ: କେବଳ ଗବେଷଣା ପାଇଁ; ଚିକିତ୍ସା ସଲାହ ନୁହେଁ","className":"important-notice","paragraphs":[{"text":"ଏହି ଉପକରଣରୁ ମିଳୁଥିବା ଯେକୌଣସି ସ୍କୋର ବା ଫଳାଫଳ କେବଳ ଗବେଷଣା ଉଦ୍ଦେଶ୍ୟରେ ଅଟେ। ଏହା ପେଶାଦାର ଡାକ୍ତରୀ ସଲାହ, ନିଦାନ ବା ଚିକିତ୍ସା ପାଇଁ ପ୍ରତିସ୍ଥାପନ ନୁହେଁ। ଏହି ଉପକରଣ CDSCO ଦ୍ୱାରା ଅନୁମୋଦିତ ନୁହେଁ ଏବଂ Software as a Medical Device (SaMD) ଭାବରେ ପ୍ରମାଣିତ ନୁହେଁ। କୌଣସି ସ୍ୱାସ୍ଥ୍ୟ ସମସ୍ୟା ପାଇଁ ଦୟାକରି ଯୋଗ୍ୟ ଡାକ୍ତରଙ୍କ ସହ ସମ୍ପର୍କ କରନ୍ତୁ।"}]},{"heading":"7) ଡାଟା ଏବଂ ଗୋପନୀୟତା (ଅଜ୍ଞାତ ସର୍ବେ)","paragraphs":[{"text":"ଆମେ କୌଣସି ବ୍ୟକ୍ତିଗତ ପରିଚୟ ସୂଚନା (ଯେପରିକି ନାମ, ଫୋନ, ଇମେଲ, ଠିକଣା, ଜାତୀୟ ID) ସଂଗ୍ରହ କରୁନାହିଁ। ଆପଣଙ୍କ ଉତ୍ତର ଅଜ୍ଞାତ ଭାବରେ ରେକର୍ଡ ହୁଏ। ଯେହେତୁ ସର୍ବେ ଅଜ୍ଞାତ, ଆପଣଙ୍କ ଉତ୍ତର ପରେ ସେଗୁଡ଼ିକୁ ଆମେ ମିଟାଇପାରୁ ନାହିଁ।"},{"strong":"ତକନିକୀ ଲଗ୍:","text":"ଆମେ ସିଷ୍ଟମକୁ ଏମିତି ଭାବେ ସେଟ୍ କରିଛୁ ଯେ IP ଠିକଣା ଓ ଡିଭାଇସ ପରିଚୟକାରୀଗୁଡ଼ିକୁ ଅସ୍ଥାୟୀ ପ୍ରକ୍ରିୟା ପରେ ରଖା ଯାଉନାହିଁ। ଯଦି ସୁରକ୍ଷା ବା କାର୍ଯ୍ୟକ୍ଷମତା ପାଇଁ ଅଲ୍ପ ଲଗ୍ ତିଆରି ହୁଏ, ସେଗୁଡ଼ିକ ଆପଣଙ୍କ ଉତ୍ତର ସହ ସଂଯୁକ୍ତ ନୁହେଁ ଏବଂ ସଂସ୍ଥାଗତ ନୀତି ଅନୁସାରେ ମିଟାଯାଏ।","className":"sub-point"},{"strong":"ସୁରକ୍ଷା:","text":"ଡାଟା ସୁରକ୍ଷିତ, ପ୍ରବେଶ ନିୟନ୍ତ୍ରିତ ସିଷ୍ଟମରେ ସଂଗ୍ରହ କରାଯାଏ, ଯେଠାରେ ଗୁପ୍ତିକରଣ ଓ ଭୂମିକା ଆଧାରିତ ପ୍ରବେଶ ନିୟନ୍ତ୍ରଣ ରହିଛି।","className":"sub-point"}]},{"heading":"8) ଡାଟା ବ୍ୟବହାର, ଅଂଶୀଦାରି ଓ ରଖା","paragraphs":[{"strong":"ଉଦ୍ଦେଶ୍ୟ ସୀମାବଧ:","text":"ଡାଟା କେବଳ ସ୍ତନ କ୍ୟାନ୍ସର ଝୁମୁକ ତଥ୍ୟ ଓ ମଡେଲ ଉନ୍ନତି/ପ୍ରମାଣିକରଣ ସହିତ ସମ୍ବନ୍ଧିତ ଶିକ୍ଷାଗତ ଗବେଷଣା ପାଇଁ ବ୍ୟବହାର ହେବ।","className":"sub-point"},{"strong":"ଅଂଶୀଦାରି:","text":"କେବଳ ଅଜ୍ଞାତ ବା ସଂଯୁକ୍ତ ଡାଟାସେଟ୍ ଗୁଡ଼ିକୁ ଗବେଷଣା ସହଯୋଗୀ ଏବଂ ଶିକ୍ଷାଗତ ସାଥିମାନଙ୍କ ସହ ସେୟାର କରାଯାଇପାରେ। ପ୍ରକାଶନଗୁଡ଼ିକରେ ବ୍ୟକ୍ତିଗତ ପରିଚୟ ବିନା ସଂଯୁକ୍ତ ଫଳାଫଳ ଦିଆଯିବ।","className":"sub-point"},{"strong":"ରଖା:","text":"ଅଜ୍ଞାତ ଡାଟାସେଟ୍ ଗୁଡ଼ିକୁ ପୁନରାବୃତି ଏବଂ ଅଡିଟ୍ ପାଇଁ ସଂସ୍ଥା/IEC ନୀତି ଅନୁସାରେ ରଖାଯାଇପାରେ।","className":"sub-point"}]},{"heading":"9) ଖର୍ଚ୍ଚ ଏବଂ ପରିଶୋଧନା","paragraphs":[{"text":"ଏହି ଅଧ୍ୟୟନରେ ଅଂଶଗ୍ରହଣ ପାଇଁ ଆପଣଙ୍କୁ କୌଣସି ଖର୍ଚ୍ଚ ନ ହେବ ଏବଂ ଆପଣଙ୍କୁ ପରିଶୋଧନା ମିଳିବ ନାହିଁ। ଏହା ଅତ୍ୟଳ୍ପ ଝୁମୁକ ସର୍ବେ ଅଧ୍ୟୟନ ହେତୁ ଆହତି ପାଇଁ କୌଣସି ପରିଶୋଧନା ଉପଲବ୍ଧ ନୁହେଁ।"}]},{"heading":"10) ସମ୍ପର୍କ ସୂଚନା (Contact Information)","paragraphs":[{"text":"ଯଦି ଆପଣ ଅଧ୍ୟୟନରୁ ସ୍ୱତନ୍ତ୍ର କୌଣସି ବ୍ୟକ୍ତିଙ୍କ ସହ କଥା ହେବାକୁ ଚାହାଁନ୍ତି, ଆପଣ ସମ୍ପର୍କ କରିପାରିବେ:"},{"strong":"ସଂସ୍ଥାଗତ ନୈତିକତା କମିଟି (IEC)","text":""},{"strong":"ନାମ (Name):","text":"Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH"},{"strong":"ଇମେଲ (Email):","text":"secretary.iec@tanuh.ai"},{"strong":"ଫୋନ (Phone#):","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"ସ୍ୱୀକାର କରନ୍ତୁ ଏବଂ ଆଗକୁ ବଢ଼ନ୍ତୁ"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'pa','{"title":"ਅਧਿਐਨ ਬਾਰੇ ਭਾਗੀਦਾਰ ਜਾਣਕਾਰੀ","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"ਅਧਿਐਨ ਸਿਰਲੇਖ","sponsor":"ਸਪਾਂਸਰ","iecApproval":"IEC ਮਨਜ਼ੂਰੀ"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) ਨਿਯੋਤਾ ਅਤੇ ਸੁਚੇਤ ਭਾਗੀਦਾਰੀ","paragraphs":[{"text":"ਤੁਹਾਨੂੰ ਭਾਰਤੀ ਆਬਾਦੀ ਵਿੱਚ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਖਤਰੇ ਦੇ ਕਾਰਕਾਂ ਬਾਰੇ ਖੋਜ ਅਧਿਐਨ ਵਿੱਚ ਭਾਗ ਲੈਣ ਲਈ ਸੱਦਾ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ। ਭਾਗੀਦਾਰੀ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸੁਚੇਤ ਹੈ। ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਭਾਗ ਨਾ ਲੈਣ ਦਾ ਫੈਸਲਾ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਇਸ ਨਾਲ ਤੁਹਾਨੂੰ ਕੋਈ ਸਜ਼ਾ ਜਾਂ ਲਾਭ ਦੀ ਹਾਨੀ ਨਹੀਂ ਹੋਵੇਗੀ।"},{"strong":"ਯੋਗਤਾ:","text":"ਤੁਹਾਡੀ ਉਮਰ ਘੱਟੋ-ਘੱਟ 18 ਸਾਲ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ। ਜੇ ਤੁਸੀਂ 18 ਸਾਲ ਤੋਂ ਘੱਟ ਉਮਰ ਦੇ ਹੋ, ਕਿਰਪਾ ਕਰਕੇ ਅੱਗੇ ਨਾ ਵਧੋ।","className":"sub-point"}]},{"heading":"2) ਅਧਿਐਨ ਦਾ ਉਦੇਸ਼","paragraphs":[{"text":"ਅਸੀਂ ਸਰਵੇਖਣ ਦੇ ਜਵਾਬਾਂ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰਾਂਗੇ ਤਾਂ ਜੋ ਭਾਰਤ ਵਿੱਚ ਛਾਤੀ ਕੈਂਸਰ ਦੇ ਖਤਰੇ ਦੇ ਕਾਰਕਾਂ ਨੂੰ ਸਮਝ ਸਕੀਏ ਅਤੇ 5 ਸਾਲ ਅਤੇ ਜੀਵਨਕਾਲ ਦੇ ਖਤਰੇ ਦਾ ਅੰਦਾਜ਼ਾ ਲਗਾਉਣ ਲਈ ਖੋਜ ਮਾਡਲ ਵਿਕਸਿਤ ਕਰ ਸਕੀਏ। ਇਹ ਸੰਦ ਅਜੇ ਵਿਕਾਸ ਅਧੀਨ ਹੈ, ਇਹ ਮੈਡੀਕਲ ਵਰਤੋਂ ਲਈ ਨਹੀਂ ਹੈ ਅਤੇ ਨਾ ਹੀ ਇਹ ਕੋਈ ਨਿਦਾਨ ਜਾਂ ਇਲਾਜ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ।"}]},{"heading":"3) ਤੁਸੀਂ ਕੀ ਕਰੋਗੇ","paragraphs":[{"text":"ਲੋਕਗਣਨਾ ਅਤੇ ਸਿਹਤ ਕਾਰਕਾਂ ਨਾਲ ਸੰਬੰਧਿਤ ਇੱਕ ਵਾਰ ਦੀ ਪ੍ਰਸ਼ਨਾਵਲੀ ਭਰੋ। ਅਨੁਮਾਨਿਤ ਸਮਾਂ ਲਗਭਗ 5–7 ਮਿੰਟ ਹੈ। ਤੁਸੀਂ ਉਹ ਪ੍ਰਸ਼ਨ ਛੱਡ ਸਕਦੇ ਹੋ ਜਿਨ੍ਹਾਂ ਦਾ ਜਵਾਬ ਦੇਣਾ ਤੁਹਾਡੇ ਲਈ ਅਸੁਖਾਵਾਂਦ ਹੈ।"}]},{"heading":"4) ਜੋਖਮ ਅਤੇ ਅਸੁਖਾਵਾਂ","paragraphs":[{"text":"ਜੋਖਮ ਬਹੁਤ ਘੱਟ ਹਨ, ਪਰ ਕੁਝ ਵਿਅਕਤੀਗਤ ਪ੍ਰਸ਼ਨ ਤੁਹਾਨੂੰ ਅਸੁਖਾਵਾਂ ਪੈਦਾ ਕਰ ਸਕਦੇ ਹਨ। ''ਡਾਟਾ ਅਤੇ ਗੋਪਨੀਯਤਾ'' ਭਾਗ ਵਿੱਚ ਵਰਣਨ ਕੀਤੇ ਗਏ ਸੁਰੱਖਿਆ ਉਪਾਅ ਡਾਟਾ ਲੀਕ ਦੇ ਜੋਖਮ ਨੂੰ ਘਟਾਉਂਦੇ ਹਨ।"}]},{"heading":"5) ਫਾਇਦੇ","paragraphs":[{"text":"ਤੁਹਾਨੂੰ ਕੋਈ ਸਿੱਧਾ ਫਾਇਦਾ ਨਹੀਂ ਹੋਵੇਗਾ। ਨਤੀਜੇ ਭਾਰਤ ਵਿੱਚ ਛਾਤੀ ਕੈਂਸਰ ਦੇ ਖਤਰੇ ਦੇ ਕਾਰਕਾਂ ਨੂੰ ਸਮਝਣ ਅਤੇ ਭਵਿੱਖ ਦੇ ਖੋਜ ਸੰਦਾਂ ਨੂੰ ਵਿਕਸਿਤ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦੇ ਹਨ।"}]},{"heading":"6) ਮਹੱਤਵਪੂਰਣ: ਕੇਵਲ ਖੋਜ ਲਈ; ਮੈਡੀਕਲ ਸਲਾਹ ਨਹੀਂ","className":"important-notice","paragraphs":[{"text":"ਇਸ ਸੰਦ ਤੋਂ ਮਿਲੇ ਕਿਸੇ ਵੀ ਸਕੋਰ ਜਾਂ ਨਤੀਜੇ ਸਿਰਫ਼ ਖੋਜ ਲਈ ਹਨ। ਇਹ ਪ੍ਰੋਫੈਸ਼ਨਲ ਮੈਡੀਕਲ ਸਲਾਹ, ਨਿਦਾਨ ਜਾਂ ਇਲਾਜ ਦਾ ਬਦਲ ਨਹੀਂ ਹਨ। ਇਹ ਸੰਦ CDSCO ਦੁਆਰਾ ਮਨਜ਼ੂਰ ਨਹੀਂ ਹੈ ਅਤੇ ਮੈਡੀਕਲ ਸੌਫਟਵੇਅਰ (SaMD) ਵਜੋਂ ਪ੍ਰਮਾਣਿਤ ਨਹੀਂ ਹੈ। ਕਿਸੇ ਵੀ ਸਿਹਤ ਸੰਬੰਧੀ ਚਿੰਤਾ ਲਈ ਕਿਰਪਾ ਕਰਕੇ ਯੋਗ ਡਾਕਟਰ ਨਾਲ ਸਲਾਹ ਕਰੋ।"}]},{"heading":"7) ਡਾਟਾ ਅਤੇ ਗੋਪਨੀਯਤਾ (ਅਗਿਆਤ ਸਰਵੇਖਣ)","paragraphs":[{"text":"ਅਸੀਂ ਕੋਈ ਵੀ ਵਿਅਕਤੀਗਤ ਪਛਾਣ ਜਾਣਕਾਰੀ (ਜਿਵੇਂ ਕਿ ਨਾਮ, ਫੋਨ, ਈਮੇਲ, ਪਤਾ, ਆਈਡੀ) ਇਕੱਠੀ ਨਹੀਂ ਕਰਦੇ। ਤੁਹਾਡੇ ਜਵਾਬ ਕਿਸੇ ਵੀ ਪਛਾਣ ਨਾਲ ਨਹੀਂ ਜੋੜੇ ਜਾਂਦੇ। ਜਦੋਂ ਤੁਸੀਂ ਆਪਣੇ ਜਵਾਬ ਭੇਜਦੇ ਹੋ, ਅਸੀਂ ਉਹਨਾਂ ਨੂੰ ਮਿਟਾ ਨਹੀਂ ਸਕਦੇ ਕਿਉਂਕਿ ਅਸੀਂ ਨਹੀਂ ਜਾਣਦੇ ਕਿ ਕਿਹੜੇ ਜਵਾਬ ਤੁਹਾਡੇ ਹਨ।"},{"strong":"ਤਕਨੀਕੀ ਲਾਗ:","text":"ਅਸੀਂ ਸਿਸਟਮਾਂ ਨੂੰ IP ਪਤੇ ਜਾਂ ਜੰਤਰ ਪਛਾਣਕਰਤਾਵਾਂ ਨੂੰ ਪ੍ਰਕਿਰਿਆ ਦੇ ਤੁਰੰਤ ਬਾਅਦ ਸਟੋਰ ਨਾ ਕਰਨ ਲਈ ਕਨਫਿਗਰ ਕੀਤਾ ਹੈ। ਜੇਕਰ ਸੁਰੱਖਿਆ ਜਾਂ ਪ੍ਰਦਰਸ਼ਨ ਲਈ ਸੀਮਤ ਲਾਗ ਉਤਪੰਨ ਹੁੰਦੇ ਹਨ, ਉਹ ਤੁਹਾਡੇ ਜਵਾਬਾਂ ਨਾਲ ਨਹੀਂ ਜੋੜੇ ਜਾਂਦੇ ਅਤੇ ਸੰਗਠਨ ਦੀ ਨੀਤੀ ਅਨੁਸਾਰ ਮਿਟਾਏ ਜਾਂਦੇ ਹਨ।","className":"sub-point"},{"strong":"ਸੁਰੱਖਿਆ:","text":"ਡਾਟਾ ਸੁਰੱਖਿਅਤ, ਪਹੁੰਚ-ਨਿਯੰਤਰਿਤ ਪ੍ਰਣਾਲੀਆਂ ਵਿੱਚ ਸਟੋਰ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਇਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਭੂਮਿਕਾ-ਅਧਾਰਿਤ ਪਹੁੰਚ ਨਿਯੰਤਰਣ ਵਰਗੇ ਉਚਿਤ ਤਕਨੀਕੀ ਅਤੇ ਸੰਗਠਨਾਤਮਕ ਉਪਾਅ ਹਨ।","className":"sub-point"}]},{"heading":"8) ਡਾਟਾ ਦੀ ਵਰਤੋਂ, ਸਾਂਝਾ ਕਰਨਾ ਅਤੇ ਰੱਖ ਰਖਾਵ","paragraphs":[{"strong":"ਉਦੇਸ਼ ਸੀਮਾ:","text":"ਡਾਟਾ ਦਾ ਵਰਤੋਂ ਸਿਰਫ਼ ਛਾਤੀ ਕੈਂਸਰ ਦੇ ਜੋਖਮ ਕਾਰਕਾਂ ਅਤੇ ਮਾਡਲ ਵਿਕਾਸ/ਪ੍ਰਮਾਣੀਕਰਨ ਨਾਲ ਸੰਬੰਧਤ ਅਕਾਦਮਿਕ ਖੋਜ ਲਈ ਕੀਤਾ ਜਾਵੇਗਾ।","className":"sub-point"},{"strong":"ਸਾਂਝਾ ਕਰਨਾ:","text":"ਕੇਵਲ ਅਗਿਆਤ ਜਾਂ ਸੰਕਲਿਤ ਡਾਟਾਸੈੱਟਾਂ ਨੂੰ ਖੋਜ ਸਹਿਯੋਗੀਆਂ ਅਤੇ ਅਕਾਦਮਿਕ ਭਾਗੀਦਾਰਾਂ ਨਾਲ ਸਾਂਝਾ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ। ਪ੍ਰਕਾਸ਼ਨਾਂ ਵਿੱਚ ਵਿਅਕਤੀਆਂ ਦੀ ਪਛਾਣ ਤੋਂ ਬਿਨਾਂ ਸਮੂਹਕ ਨਤੀਜੇ ਪੇਸ਼ ਕੀਤੇ ਜਾਣਗੇ।","className":"sub-point"},{"strong":"ਰੱਖ ਰਖਾਵ:","text":"ਅਗਿਆਤ ਡਾਟਾਸੈੱਟਾਂ ਨੂੰ ਸੰਸਥਾ/IEC ਨੀਤੀ ਅਨੁਸਾਰ ਪੁਨਰ-ਵਿਸ਼ਲੇਸ਼ਣ ਅਤੇ ਆਡਿਟ ਲਈ ਰੱਖਿਆ ਜਾ ਸਕਦਾ ਹੈ।","className":"sub-point"}]},{"heading":"9) ਲਾਗਤ ਅਤੇ ਮੁਆਵਜ਼ਾ","paragraphs":[{"text":"ਭਾਗੀਦਾਰੀ ਲਈ ਤੁਹਾਨੂੰ ਕੋਈ ਲਾਗਤ ਨਹੀਂ ਆਵੇਗੀ ਅਤੇ ਤੁਹਾਨੂੰ ਕੋਈ ਭੁਗਤਾਨ ਨਹੀਂ ਕੀਤਾ ਜਾਵੇਗਾ। ਇਹ ਘੱਟ ਜੋਖਮ ਵਾਲਾ ਸਰਵੇਖਣ ਅਧਿਐਨ ਹੈ, ਇਸ ਲਈ ਚੋਟ ਲਈ ਕੋਈ ਮੁਆਵਜ਼ਾ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।"}]},{"heading":"10) ਸੰਪਰਕ ਜਾਣਕਾਰੀ (Contact Information)","paragraphs":[{"text":"ਜੇ ਤੁਸੀਂ ਅਧਿਐਨ ਤੋਂ ਸੁਤੰਤਰ ਕਿਸੇ ਵਿਅਕਤੀ ਨਾਲ ਗੱਲ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਸੰਪਰਕ ਕਰ ਸਕਦੇ ਹੋ:"},{"strong":"ਸੰਸਥਾਗਤ ਨੈਤਿਕਤਾ ਕਮੇਟੀ (IEC)","text":""},{"strong":"ਨਾਮ (Name):","text":"Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH"},{"strong":"ਈਮੇਲ (Email):","text":"secretary.iec@tanuh.ai"},{"strong":"ਫੋਨ (Phone#):","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"ਸਵੀਕਾਰ ਕਰੋ ਅਤੇ ਅੱਗੇ ਵਧੋ"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'ta','{"title":"ஆய்வு பற்றிய பங்கேற்பாளர் தகவல்","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"ஆய்வு தலைப்பு","sponsor":"ஆதார நிறுவனம்","iecApproval":"IEC அங்கீகாரம்"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) அழைப்பு மற்றும் தன்னார்வ பங்கேற்பு","paragraphs":[{"text":"இந்திய மக்களிடையே மார்பகப் புற்றுநோய் அபாயக் காரணிகளைப் பற்றிய ஆய்வில் பங்கேற்க உங்களை அழைக்கப்படுகிறது. பங்கேற்பு முழுமையாக தன்னார்வமானது. நீங்கள் பங்கேற்க மறுத்தாலும் எந்தவித தண்டனையோ அல்லது நன்மை இழப்போ இல்லை."},{"strong":"தகுதி:","text":"நீங்கள் 18 வயது அல்லது அதற்கு மேற்பட்டவராக இருக்க வேண்டும். நீங்கள் 18 வயதிற்குக் குறைந்தவராக இருந்தால், தயவுசெய்து தொடர வேண்டாம்.","className":"sub-point"}]},{"heading":"2) ஆய்வின் நோக்கம்","paragraphs":[{"text":"இந்தியாவில் மார்பகப் புற்றுநோய் அபாயக் காரணிகளைப் புரிந்து கொள்ளவும், 5 ஆண்டுகள் மற்றும் வாழ்நாள் அபாயத்தைக் கணிக்கும் ஆராய்ச்சி நோக்கத்திற்கான மாதிரியை உருவாக்கவும், கேள்வித்தாளின் பதில்கள் பகுப்பாய்வு செய்யப்படும். இந்த கருவி இன்னும் மேம்பாட்டில் உள்ளது, மருத்துவ பயன்பாட்டிற்காக அல்ல, மேலும் இது மருத்துவ நோயறிதல் அல்லது சிகிச்சையை வழங்காது."}]},{"heading":"3) நீங்கள் செய்ய வேண்டியது","paragraphs":[{"text":"மக்கள்தொகை மற்றும் உடல்நல தொடர்பான காரணிகளைப் பற்றிய ஒருமுறை கேள்வித்தாளை நிரப்ப வேண்டும். இதற்காக சுமார் 5–7 நிமிடங்கள் ஆகும். நீங்கள் சிரமமாக உணரும் கேள்விகளைத் தவிர்க்கலாம்."}]},{"heading":"4) அபாயங்கள் மற்றும் சிரமங்கள்","paragraphs":[{"text":"அபாயங்கள் மிகக் குறைவாக உள்ளன, ஆனால் சில கேள்விகள் தனிப்பட்டதாக இருப்பதால் சிறிய சிரமம் ஏற்படலாம். \\"தரவு மற்றும் தனியுரிமை\\" பிரிவில் விவரிக்கப்பட்ட பாதுகாப்பு நடவடிக்கைகள் மூலம் தரவு கசிவு அபாயம் குறைக்கப்படுகிறது."}]},{"heading":"5) நன்மைகள்","paragraphs":[{"text":"நீங்கள் நேரடி நன்மையைப் பெற வாய்ப்பில்லை. இந்த ஆய்வு இந்தியாவில் மார்பகப் புற்றுநோய் அபாயக் காரணிகளைப் புரிந்துகொள்வதற்கும் எதிர்கால ஆய்வு கருவிகளை மேம்படுத்துவதற்கும் உதவும்."}]},{"heading":"6) முக்கியம்: ஆராய்ச்சி நோக்கத்திற்கே; மருத்துவ ஆலோசனை அல்ல","className":"important-notice","paragraphs":[{"text":"இந்த கருவி வழங்கும் எந்த மதிப்பெண் அல்லது முடிவும் ஆராய்ச்சி நோக்கத்திற்காக மட்டுமே. இது தொழில்முறை மருத்துவ ஆலோசனை, நோயறிதல் அல்லது சிகிச்சைக்கான மாற்றாகாது. இந்த கருவி CDSCO ஆல் அங்கீகரிக்கப்படவில்லை மற்றும் இது மருத்துவ மென்பொருளாக (SaMD) சான்றளிக்கப்படவில்லை. உடல்நலப் பிரச்சினைகள் இருந்தால், தகுதியான மருத்துவரை அணுகவும்."}]},{"heading":"7) தரவு மற்றும் தனியுரிமை (அடையாளமற்ற கருத்துக்கணிப்பு)","paragraphs":[{"text":"நாங்கள் எந்த தனிப்பட்ட அடையாளத் தகவல்களையும் (உதா., பெயர், தொலைபேசி, மின்னஞ்சல், சரியான முகவரி, அடையாள எண்) சேகரிக்கவில்லை. உங்கள் பதில்கள் அடையாளத்துடன் இணைக்கப்படாமல் பதிவு செய்யப்படும். சமர்ப்பித்த பிறகு உங்கள் பதில்களை எங்களால் நீக்க முடியாது, ஏனெனில் அவை அடையாளமற்றவை."},{"strong":"தொழில்நுட்ப பதிவுகள்:","text":"IP முகவரிகள் அல்லது சாதன அடையாளங்களை தற்காலிக செயலாக்கத்தைத் தாண்டி சேமிக்காமல் இருக்க அமைப்புகள் வடிவமைக்கப்பட்டுள்ளன. பாதுகாப்பு அல்லது செயல்திறன் காரணமாக குறைந்த அளவு பதிவு உருவாகினாலும், அவை உங்கள் பதில்களுடன் இணைக்கப்படாது மற்றும் நிறுவனக் கொள்கைப்படி நீக்கப்படும்.","className":"sub-point"},{"strong":"பாதுகாப்பு:","text":"தரவு பாதுகாக்கப்பட்ட, அணுகல்-கட்டுப்படுத்தப்பட்ட அமைப்புகளில் சேமிக்கப்படுகிறது, குறியாக்கம் மற்றும் பங்கு அடிப்படையிலான அணுகல் கட்டுப்பாடு போன்ற நியாயமான தொழில்நுட்ப மற்றும் அமைப்புரிமை நடவடிக்கைகளுடன்.","className":"sub-point"}]},{"heading":"8) தரவு பயன்பாடு, பகிர்வு மற்றும் பராமரிப்பு","paragraphs":[{"strong":"நோக்க வரம்பு:","text":"தரவு முழுக்க முழுக்க மார்பகப் புற்றுநோய் அபாயக் காரணிகள் மற்றும் மாதிரி உருவாக்கம்/சரிபார்ப்பு தொடர்பான கல்வி ஆராய்ச்சிக்காக மட்டுமே பயன்படுத்தப்படும்.","className":"sub-point"},{"strong":"பகிர்வு:","text":"தனிநபரை அடையாளம் காண முடியாத அல்லது தொகுக்கப்பட்ட தரவுகள் மட்டும் ஆராய்ச்சி ஒத்துழைப்பாளர்கள் மற்றும் கல்வி நிறுவனங்களுடன் அதே நோக்கத்திற்காகப் பகிரப்படும். வெளியீடுகள் அடையாளமற்ற மொத்த முடிவுகளை மட்டுமே வழங்கும்.","className":"sub-point"},{"strong":"பராமரிப்பு:","text":"அடையாளமற்ற தரவுத் தொகுப்புகள் நிறுவனம்/IEC கொள்கைக்கு ஏற்ப மீளாய்வு மற்றும் தணிக்கைக்காக வைக்கப்படலாம்.","className":"sub-point"}]},{"heading":"9) செலவுகள் மற்றும் இழப்பீடு","paragraphs":[{"text":"பங்கேற்க உங்களுக்கு எந்தச் செலவும் இல்லை, மேலும் உங்களுக்கு எந்தத் தொகையும் வழங்கப்படாது. இது குறைந்த அபாயம் கொண்ட கருத்துக்கணிப்பு ஆய்வு என்பதால், காயங்களுக்கு இழப்பீடு வழங்கப்படாது."}]},{"heading":"10) தொடர்பு விவரங்கள் (Contact Information)","paragraphs":[{"text":"நீங்கள் ஆய்வில் தொடர்பில்லாத ஒருவரிடம் பேச விரும்பினால், இவரைத் தொடர்பு கொள்ளலாம்:"},{"strong":"நிறுவன நெறிமுறைக் குழு (IEC)","text":""},{"strong":"பெயர் (Name):","text":"Dr. Sri Vidhya Jagadish, Secretary, IEC, TANUH"},{"strong":"மின்னஞ்சல் (Email):","text":"secretary.iec@tanuh.ai"},{"strong":"தொலைபேசி (Phone#):","text":"080 - 2293 4106 / 2293 4107"}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"ஏற்கவும் & தொடரவும்"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
INSERT INTO participant_information_translations(version_number,language_code,content_json,is_active) VALUES (2,'te','{"title":"అధ్యయనం గురించి పాల్గొనేవారి సమాచారం","logos":{"tanuhAlt":"TANUH Logo","iiscAlt":"IISC Logo"},"headernames":{"studyTitle":"స్టడీ పేరు","sponsor":"సహాయం అందిస్తున్నవారు","iecApproval":"IEC అనుమతి"},"header":{"studyTitle":"AI enabled Breast Cancer Screening Tool","sponsor":"TANUH Foundation","iecApproval":"Ethics committee approval received from Clinicom vide letter no: 02434 dated 13-Jan-2026"},"sections":[{"heading":"1) ఆహ్వానం మరియు ఇష్టపూర్వకంగా పాల్గొనడం","paragraphs":[{"text":"భారతదేశంలో రొమ్ము క్యాన్సర్ రిస్క్ ఫ్యాక్టర్స్‌పై చేస్తున్న ఈ పరిశోధన స్టడీలో మీరు పాల్గొనాలని కోరుతున్నాము. ఇందులో పాల్గొనడం పూర్తిగా మీ ఇష్టం. మీరు పాల్గొనకపోయినా, మీకు ఎటువంటి ఇబ్బంది లేదా నష్టం ఉండదు."},{"strong":"అర్హత:","text":"మీ వయసు తప్పనిసరిగా 18 ఏళ్లు లేదా ఆపై ఉండాలి. మీరు 18 ఏళ్ల కంటే తక్కువ ఉంటే, దయచేసి ముందుకు సాగవద్దు.","className":"sub-point"}]},{"heading":"2) స్టడీ ఉద్దేశం","paragraphs":[{"text":"భారతదేశంలో రొమ్ము క్యాన్సర్ రిస్క్ ఫ్యాక్టర్స్‌ను అర్థం చేసుకోవడానికి, అలాగే 5 ఏళ్లు మరియు జీవితకాల రిస్క్‌ను అంచనా వేసే పరిశోధన మోడల్‌ను తయారు చేయడానికి మేము సర్వే సమాధానాలను పరిశీలిస్తాము. ఈ టూల్ ఇంకా తయారుచేసే దశలో ఉంది, ఇది వైద్య అవసరాలకు కాదు, మరియు ఎలాంటి మెడికల్ డయాగ్నోసిస్ (నిర్ధారణ) లేదా ట్రీట్‌మెంట్ (చికిత్స) ఇవ్వదు."}]},{"heading":"3) మీరు చేయాల్సిన పని","paragraphs":[{"text":"మీ వ్యక్తిగత వివరాలు (Demographic) మరియు ఆరోగ్యానికి సంబంధించిన విషయాలపై ఒకే ఒక్కసారి ప్రశ్నావళిని పూర్తి చేయాలి. దీనికి సుమారు 5-7 నిమిషాలు పట్టవచ్చు. మీకు సమాధానం చెప్పడానికి ఇబ్బందిగా అనిపించే ఏ ప్రశ్ననైనా మీరు వదిలివేయవచ్చు లేదా స్కిప్ చేయవచ్చు"}]},{"heading":"4) ప్రమాదాలు మరియు ఇబ్బందులు","paragraphs":[{"text":"ప్రమాదాలు చాలా తక్కువగా ఉంటాయి మరియు వ్యక్తిగత ప్రశ్నల వల్ల కొంత అసౌకర్యం కలగవచ్చు. డేటా ఉల్లంఘనకు స్వల్ప ప్రమాదం ఉంది, కానీ ''డేటా మరియు గోప్యత'' విభాగంలో వివరించిన రక్షణ చర్యల ద్వారా దీన్ని తగ్గించాము."}]},{"heading":"5) ప్రయోజనాలు (Benefits)","paragraphs":[{"text":"ఈ స్టడీ వల్ల మీకు ప్రత్యేకంగా ఎలాంటి లాభం ఉండకపోవచ్చు. ఈ పరిశోధన ఫలితాలు భారతదేశంలో రొమ్ము క్యాన్సర్ ప్రమాద కారకాలపై మరింత బాగా అర్థం చేసుకోవడానికి, భవిష్యత్తులో పరిశోధనా టూల్స్ తయారు చేయడానికి ఉపయోగపడతాయి."}]},{"heading":"6) ముఖ్యం: పరిశోధన కోసమే; ఇది వైద్య సలహా కాదు","className":"important-notice","paragraphs":[{"text":"ఈ టూల్ ఇచ్చే ఏ స్కోర్ లేదా ఫలితమైనా కేవలం పరిశోధన (Research) కోసం మాత్రమే. ఇది డాక్టర్ ఇచ్చే వైద్య సలహా, డయాగ్నోసిస్ (నిర్ధారణ) లేదా ట్రీట్‌మెంట్ (చికిత్సకు) బదులు కాదు. ఈ టూల్‌కు CDSCO అనుమతి లేదు, మరియు ఇది గుర్తించబడిన Software as a Medical Device (SaMD) కూడా కాదు. మీకు ఆరోగ్య సమస్యలు ఏవైనా ఉంటే, దయచేసి తప్పనిసరిగా అర్హత ఉన్న డాక్టర్‌ను సంప్రదించండి."}]},{"heading":"7) డేటా మరియు గోప్యత (Anonymous Survey)","paragraphs":[{"text":"మేము మీ వ్యక్తిగత వివరాలు (ఉదాహరణకు, పేరు, ఫోన్ నంబర్, ఇమెయిల్, పూర్తి అడ్రస్, ఆధార్/నేషనల్ ID లాంటివి) ఏవీ సేకరించము. మీ సమాధానాలు మీ గుర్తింపుతో సంబంధం లేకుండా రికార్డ్ అవుతాయి. మీరు పంపే సమాధానాలు అనామకం (Anonymous) కాబట్టి, ఒక్కసారి పంపిన తర్వాత, అవి మీవే అని గుర్తించలేము. అందువల్ల, వాటిని వెనక్కి తీసుకోవడం లేదా తొలగించడం సాధ్యం కాదు."},{"strong":"టెక్నికల్ లాగ్స్:","text":"IP అడ్రస్‌లు లేదా డివైజ్ వివరాలు శాశ్వతంగా స్టోర్ (Store) అవ్వకుండా ఉండేలా మేము సిస్టమ్‌లను సెట్ చేస్తాము. ఒకవేళ సెక్యూరిటీ (Security) లేదా పనితీరు కోసం చిన్నపాటి లాగ్స్ నమోదైనా, అవి మీ సమాధానాలకు లింక్ కావు మరియు సంస్థ నిబంధనల ప్రకారం వాటిని తొలగిస్తారు.","className":"sub-point"},{"strong":"భద్రత:","text":"డేటాను సురక్షితమైన సిస్టమ్స్‌లో స్టోర్ చేస్తాము. ఈ సిస్టమ్స్‌కు ఎవరికి పడితే వారికి యాక్సెస్ ఉండదు. డేటా ఎన్‌క్రిప్షన్ మరియు రోల్-బేస్డ్ యాక్సెస్ కంట్రోల్స్ (అవసరమైన వారికి మాత్రమే యాక్సెస్ ఇచ్చే ఏర్పాట్లు) వంటి భద్రతా చర్యలను మేము తీసుకుంటాము.","className":"sub-point"}]},{"heading":"8) డేటా వినియోగం, పంచుకోవడం మరియు భద్రపరచడం","paragraphs":[{"strong":"ఉపయోగం పరిమితం:","text":"ఈ డేటాను కేవలం విద్యా సంబంధిత పరిశోధన (Academic Research) కోసం మాత్రమే ఉపయోగిస్తాము. ముఖ్యంగా, రొమ్ము క్యాన్సర్ ప్రమాద కారకాలు మరియు మోడల్ తయారుచేయడం/తనిఖీ (Model Development/Validation) కోసం వాడుతాము.","className":"sub-point"},{"strong":"షేర్ చేయడం:","text":"మీ గుర్తింపు లేకుండా చేసిన (De-identified) లేదా మొత్తం కలిపిన (Aggregated) డేటాను మాత్రమే పరిశోధనలో సహకరించేవారితో మరియు అకడమిక్ పార్ట్‌నర్స్‌తో అదే పని కోసం షేర్ చేయవచ్చు. ప్రచురించే రిపోర్టులలో వ్యక్తుల వివరాలు తెలియని మొత్తం ఫలితాలను మాత్రమే నివేదిస్తారు.","className":"sub-point"},{"strong":"డేటా భద్రపరచడం:","text":"అనామకమైన (Anonymous) డేటాసెట్‌లను, పరిశోధన ఫలితాల ప్రామాణికత (ఎప్పుడైనా ఫలితాలను మళ్లీ చెక్ చేసుకోవడం) మరియు ఆడిట్ కోసం, సంస్థ/IEC నిబంధనల ప్రకారం సేవ్ చేసి ఉంచుతాము (లేదా నిల్వ చేస్తాము).","className":"sub-point"}]},{"heading":"9) ఖర్చులు మరియు పరిహారం","paragraphs":[{"text":"ఈ స్టడీలో పాల్గొనడానికి మీరు ఏమీ ఖర్చు పెట్టాల్సిన అవసరం లేదు, మరియు మీకు డబ్బు చెల్లించబడదు. ఇది కేవలం తక్కువ రిస్క్ (Low-Risk) ఉన్న సర్వే స్టడీ కాబట్టి, ఏవైనా గాయాలు జరిగితే పరిహారం (Compensation) ఇవ్వడం సాధ్యం కాదు."}]}],"checkboxLabel":"By checking this box, you confirm that you are 18 years of age or older, that you have read and understood the Participant Information Sheet, and that the information you provide for this study is given voluntarily.","buttonText":"అంగీకరించండి మరియు ముందుకు వెళ్ళండి"}',1) ON DUPLICATE KEY UPDATE content_json=VALUES(content_json),is_active=1;
